// 简体中文 stories: I18N["zh-CN"].stories["<civ id>:<activity>"] = "…" (same keys as cultures/stories/westasia-africa.js).
Object.assign(I18N["zh-CN"].stories, {
  "persians-early:hunt": "在约公元600年雕凿的塔克-伊-博斯坦（طاق بستان）大岩拱中，库思老二世（خسرو پرویز）立于芦苇船上，大象正把野猪赶出沼泽，驱向他的弓前。其他船上坐着弹竖琴的女子，国王头顶的光环标明他是天选之人。对萨珊宫廷而言，在围墙环绕的王家园林“帕迪斯”（pardis）中狩猎不只是游戏：能驯服野兽的沙阿，证明自己也能让天下井然有序。",
  "persians-early:battle": "公元260年，沙普尔一世（شاپور）在埃德萨（ܐܘܪܗܝ）附近迎战罗马军队，竟俘虏了罗马皇帝瓦勒良（Valerianus）本人。人马俱披锁甲的萨瓦兰重骑兵（سواران）在号角与战鼓声中冲锋，这场胜利被刻在纳克什-伊-鲁斯塔姆（نقش رستم）的崖壁上：沙普尔骑在马上，一位罗马皇帝跪在他面前，另一位被他攥住手腕。对伊朗而言，这证明阿胡拉·马兹达（اهورامزدا）的王国足以与罗马平起平坐。",
  "persians-early:gather": "在秋季的密特拉节梅赫尔甘节（مهرگان，祭祀密特拉 مهر）上，伊朗高原的收成纷纷入仓：坎儿井浇灌的麦子、石榴、葡萄，还有黎明前一丝一丝采下的藏红花。萨珊诸王戴着太阳形的王冠，接受当季的献礼，百姓则互赠甜食与誓言。后来比鲁尼（البيروني）写道，这是波斯人仅次于诺鲁孜节（نوروز）的大节，是为一个没有歉收的年份而举行的感恩之礼。",
  "persians-early:ritual": "大战之前，萨珊诸王不骑马，而是步行前往塔赫特-苏莱曼（تخت سلیمان）的阿杜尔·古什纳斯普（آذرگشنسب）——武士的火神庙，就在一汪深蓝的泉湖旁。祭司们戴着白色面纱、掩住口鼻，以免呼吸沾污火焰，他们添上檀香木，诵读《阿维斯塔》（اوستا）。国王献上礼物，向阿胡拉·马兹达（اهورامزدا）祈求胜利。无人高声；火焰只是继续燃烧，作为回答。",
  "persians-early:rain": "《阿维斯塔》（اوستا）中，蒂什塔尔星（تیشتر）——即天狼星——在海边与旱魔阿帕奥沙（اپوش）搏斗：一匹金耳白马对一匹秃毛黑马。前三夜蒂什塔尔落败，因为人们忘了祈祷；当人们想起来，他便获胜，云层滚滚漫过大地。每年夏天的提尔甘节（تیرگان），伊朗的村庄里人们互相泼水，在手腕上系彩虹色的丝线，等待这场胜利。",
  "persians-early:flood": "约公元628年，库思老二世（خسرو پرویز）在位的最后几年，底格里斯河（دجله）与幼发拉底河（فرات）涨到前所未见的高度，冲垮了萨瓦德（سواد）——美索不达米亚肥沃黑土地——的堤坝。拜拉祖里（البلاذري）记载，国王亲临决口，堤防再次失守时便惩罚了工人。缺口终究没能堵上；洪水一留就是几个世纪，成为“大沼泽”，帝国再也没能恢复往日的收成。",
  "persians:wind": "在伊朗东部边境的锡斯坦（سیستان），“一百二十天之风”（باد صد و بیست روزه）每年夏天刮个不停。它用沙子掩埋村庄，吹得行人睁不开眼。人们并不只是忍受它：在纳什提凡（نشتیفان），用泥土和木头建成的古老立轴风车——也许是世上最古老的风车样式——至今仍在风中转动、磨着粮食。住在那里，就是与风暴结为伙伴。",
  "persians:fire": "诺鲁孜节（نوروز）前五十天的萨德节（سده），伊朗人点燃巨大的篝火，庆祝火的发现。《列王纪》（شاهنامه）讲述胡尚国王（هوشنگ）向一条蛇扔石头，没有打中，却击中岩石，看见一颗火星迸出。他向这道光鞠躬，下令设宴。火从不被当作神来崇拜，而是阿胡拉·马兹达（اهورامزدا）最纯洁的象征；隆冬的火焰预示着寒冷终将结束。",
  "persians:thunder": "想象：一位扎格罗斯山（زاگرس）的牧人赶着羊群从高山牧场下来，黑云正堆在峰顶。闪电划过山坡，他数着秒等雷声，祈祷风暴移到下一道山谷去。他的祖母说，那是天空在与旱魔交战，每一声雷鸣对山下的麦子都是好消息，哪怕它吓坏了羊群。",
  "persians:birth": "《列王纪》（شاهنامه）说，鲁达贝（رودابه）生鲁斯塔姆（رستم）时难产，几乎丧命。扎尔（زال）烧了一根西摩格（سیمرغ）的羽毛，神鸟随即现身，吩咐他让她饮酒，用刀剖开她的腹侧，把孩子抱出来，再用草药和一拂羽毛治好伤口。波斯人至今把剖腹产称为“鲁斯塔姆式生产”（رستم‌زاد）。这个又大又哭闹的婴儿，日后将一次又一次拯救伊朗。",
  "persians-early:death": "琐罗亚斯德教的葬礼安静而审慎。遗体洗净，穿上白衣，先让一条狗来看——即“犬视”（سگ‌دید），人们相信狗的目光能驱走腐秽。抬尸人两两一组把遗体送到达赫玛（دخمه）——寂静之塔，让阳光和飞鸟把它归还自然，而不玷污土地与火。送葬者两人一组牵着一块布跟随其后，祭司诵读《阿维斯塔》（اوستا）；第四天黎明，灵魂走过钦瓦特桥（پل چینود）。",
  "persians-early:voyage": "库思老一世·阿努希尔万（انوشیروان）派御医布尔佐伊（برزویه）前往印度，寻找一部据说藏在那里的智慧之书。布尔佐伊游历多年，学会了梵语，秘密抄下了《五卷书》（पञ्चतन्त्र）中的动物寓言。他回到泰西封（تیسفون）后，国王让人在宫廷上用中古波斯语朗读这些故事。后来译成阿拉伯文的《卡里来和笛木乃》（كليلة ودمنة），让这些豺狼的故事传遍了半个世界。",
  "persians-early:festival": "在萨珊宫廷，诺鲁孜节（نوروز）要持续好几天。国王按品级接受献礼：糖、白银、骏马、新铸的钱币。菲尔多西（فردوسی）及后世作家讲过一个故事：年轻的乐师巴尔巴德（باربد）被一个嫉妒的对手挡在宫外，便身穿绿衣藏进御花园的一棵柏树里。库思老二世（خسرو پرویز）设宴时，歌声一首接一首从枝叶间传来，直到国王把这位隐身的歌者唤出，任命他为乐师之首。",
  "persians-early:games": "中古波斯语的《象棋释义》（چترنگ‌نامگ）讲述，一位印度国王给库思老一世（انوشیروان）送来一种新游戏——恰特兰格（چترنگ），即象棋，并附上挑战：讲出玩法，否则就纳贡。两天里无人能解。第三天，贤相布祖尔格米赫尔（بزرگمهر）起身，把棋子看作一支军队，与使者对弈并获胜。随后他自创了一种游戏——纳尔德（نرد），即双陆，以骰子象征运转的天穹，送往印度。",
  "persians-early:drought": "史家塔巴里（الطبري）记载，5世纪后期卑路斯（پیروز）在位时，连续七年无雨。泉水和坎儿井干涸，河流萎缩，整个高原的田地一片枯黄。卑路斯免除了土地税，打开王家粮仓，命富人分粮，并警告说：若哪个村子有人饿死，全村都要担责。等雨终于回来时，据说没有一个人死于饥荒。",
  "persians-early:wind": "想象：在戈尔甘长城（سد اسکندر）——萨珊诸王沿草原修筑的砖砌城墙——上，一个年轻士兵在冬夜站岗。北风从开阔的草原上毫无阻拦地刮来，吹得堡垒的芦苇屋顶簌簌作响，把炊烟压成平平一线。一位老战友掏出一支奈伊笛（نی），吹起一支来自法尔斯故乡的慢调。风把笛声沿着城墙向东带去，送往下一座堡垒，再下一座。",
  "persians-early:fire": "每一枚萨珊钱币上都有火坛，每位国王登基时都要点燃属于自己的圣火。3世纪末，大祭司卡尔提尔（کرتیر）把自己的功业刻在纳克什-伊-拉贾布（نقش رجب）的岩石和“琐罗亚斯德天房”上：他说自己在全国建立了许多巴赫拉姆圣火（آتش بهرام），并任命祭司守护。无论村中神龛还是王家神庙，火焰都日夜添以干柴和香料，永不熄灭。",
  "persians-early:thunder": "想象：一场夏日风暴降临泰西封（تیسفون）。在库思老一世的砖砌巨拱——塔克-基斯拉（طاق کسری）之下，宫廷众人等着雨停。雷声滚过底格里斯河（دجله），在大厅里轰鸣，如同一面巨鼓。一位竖琴女乐师笑着把她的竖琴（چنگ）调到雷声的音高，在雷鸣间隙弹奏，歌者即兴唱出一句：连天空都来赞美国王的盛宴。那座不用拱架建成的穹顶，连颤都没颤一下。",
  "persians-early:quake": "想象：在沙普尔一世于法尔斯山谷中修建的比沙普尔城（بیشاپور），黎明前大地震动。一家家人穿着睡衣跑上柱廊街道；几根柱子裂了，一个商人家的屋梁塌落。天亮后，人们聚在王宫庭院，那里描绘乐师与舞女的马赛克地面一角裂开了。当天早上就请来了工匠。到下一个节日，舞女们又被拼合起来，只是有点歪。",
  "persians-early:winter": "为了让宫廷在冬天也留住春天，萨珊诸王为泰西封（تیسفون）的宫殿织了一张巨毯：“库思老之春”（بهار کسری）。阿拉伯史家描述它长约三十米，是一座用金银线织成的花园：水晶的溪流，红宝石和珍珠的花朵，祖母绿的绿野。当扎格罗斯山（زاگرس）积雪、园林凋零时，国王与宾客坐在毯上饮酒听乐，仿佛正值四月。",
  "persians-early:birth": "309年国王霍尔米兹德二世（هرمزد）去世时，王后正怀着身孕。塔巴里（الطبري）记载，渴望有一位国王的贵族和祭司把王冠放在她的腹上，占星家们预言会生一个儿子。于是沙普尔二世（شاپور）尚未出生便已加冕，据说是唯一一位在母腹中加冕的国王。他年幼时由大臣以他的名义摄政；十六岁时他亲掌大权，在位长达七十年。",
  "persians-early:wedding": "库思老二世（خسرو پرویز）爱上了来自胡齐斯坦的阿拉米基督徒希琳（شیرین），立她为王后。宫廷以音乐庆贺：巴尔巴德（باربد）和竖琴师纳基萨（نکیسا）在王家宴会上唱的歌流传至今。几个世纪后，诗人内扎米（نظامی）把他们的爱情写成了叙事诗《霍斯陆与希琳》（خسرو و شیرین），诗中法尔哈德（فرهاد）为她凿穿了一座山。诗里的乐师们通宵歌唱，恋人们以歌相和。",
  "persians:hunt": "1848年起在位的纳赛尔丁沙（ناصرالدین شاه）几乎比什么都爱狩猎。在贾吉鲁德（جاجرود）河谷和拉尔（لار）的高山草甸，他带着一整座帐篷城、赶兽人、鹰师和厨子扎营数周，每天在日记里记下猎物：北山羊、野绵羊、石鸡。他还带了相机，摄影师们留下了骑手、猎犬和篝火边疲惫仆从的照片。晚上，乐师们在御帐里奏乐。",
  "persians:battle": "1514年8月，在查尔迪兰（چالدران），年轻的伊斯玛仪沙（شاه اسماعیل）麾下戴红缨帽的奇兹尔巴什（قزلباش）骑兵冲向奥斯曼阵线。他们第一次遭遇如此规模的大炮和火枪齐射，没能冲破。以哈塔伊（خطایی）为笔名用突厥语写诗的伊斯玛仪负伤撤退。此后萨法维军队学会了新式武器，士兵们的歌谣则记住了那些没能回家的骑手。",
  "persians:siege": "1622年初，伊玛目库里汗（امامقلی خان）率领的萨法维军队在英国舰船封锁海面的配合下，围攻霍尔木兹岛（هرمز）上的葡萄牙要塞。士兵们挖了十周的壕沟和坑道，直通城墙之下，舰炮则轰击不停。城内粮水断绝，5月要塞投降。岛上的贸易转移到大陆的港口，阿拔斯沙（شاه عباس）以自己的名字将其命名为阿巴斯港（بندرعباس）。",
  "persians:triumph": "1740年，纳迪尔沙（نادرشاه）带着德里的宝藏回国：孔雀宝座（تخت طاووس）、成箱的黄金，以及巨钻“光之山”（کوه نور）。为了庆祝，他免除全伊朗三年的赋税。各城的鼓乐楼（نقاره‌خانه）里鼓声与卡尔奈长号（کرنای）齐鸣，象队和驼队穿街而过。远征德里的士兵们带回了故事，也带回了一点银子。",
  "persians:gather": "每年五月，在卡尚（کاشان）附近的卡姆萨尔（قمصر），家家户户在日出前采摘粉色的大马士革玫瑰，那时香气最浓。花瓣直接放进柴火上的铜锅，蒸汽经管道流入冷水，凝成玫瑰水（گلاب）。萨法维时代的旅行者已写到卡尚的玫瑰水，远销印度和奥斯曼领土。在“玫瑰水节”（گلاب‌گیری），整个河谷弥漫着玫瑰香，朝圣者把一瓶瓶玫瑰水带回家，用于甜点、祈祷和婚礼。",
  "persians:build": "1598年至1629年间，阿拔斯沙（شاه عباس）为伊斯法罕（اصفهان）建造了新的中心：伊玛目广场（نقش جهان），长逾五百米，四周环绕着两层商铺。工匠们建起了沙阿清真寺和谢赫·洛特夫拉清真寺，穹顶覆以成千上万烧制的蓝色瓷砖，还有阿里卡普宫（عالی‌قاپو），其音乐厅的墙壁凿满了花瓶形的壁龛。日落时分，集市门楼上的鼓乐楼乐队奏响鼓与号角。",
  "persians:ritual": "在祖尔哈奈（زورخانه）——“力量之屋”里，男人们在低于地面的八角形坑中训练。导师（مرشد）坐在高处，敲着扎尔布鼓（ضرب），摇铃，吟唱《列王纪》（شاهنامه）和哈菲兹（حافظ）的诗句。运动员们随着他的节奏挥舞沉重的木棒，推举木板，并一个接一个在中央旋转。旅行者曾描述萨法维和恺加时代城镇中的祖尔哈奈；最年长的冠军仍领头行礼，最年轻的最后入场。",
  "persians:rain": "在伊朗乡村，雨水迟迟不来时，孩子们会玩“勺子新娘”（چمچه‌گلین）。19至20世纪的民族志学者在许多省份记录过它：女孩们给一把大木勺裹上头巾和鲜艳的布，挨家挨户地走，唱道：勺子新娘想要什么？她向真主要雨。每户人家往玩偶身上浇一点水，再往孩子们的碗里放面粉、油或米。事后大家一起把这些食物煮来吃。",
  "persians:flood": "想象：恺加王朝的一个春天，扎格罗斯山（زاگرس）的积雪迅速融化，卡伦河（کارون）浑黄湍急地涨过舒什塔尔（شوشتر）。古老的堰坝呻吟着；河水漫进小巷和集市。店主们把成匹的布料堆上高架，船夫们把老奶奶们渡到山坡上的清真寺。水退之后，大家一起铲泥。那天晚上的茶馆里，一个人弹着塔尔琴（تار），唱起巴巴·塔赫尔（باباطاهر）一段哀伤的诗句，有人则用一个笑话回应。",
  "persians:plague": "1830年和1831年，霍乱和随后的鼠疫横扫里海沿岸的吉兰省（گیلان）。英国和俄国的观察者报告，拉什特（رشت）城中大半居民或死或逃；蚕场无人照看，桑叶烂在树上。能逃的人家躲进山里；留下的人匆匆把死者葬在园子里。疫病过后，幸存者回到空荡荡的房屋，从大不里士（تبریز）来的丝商发现几乎找不到织工可买货了。",
  "persians:death": "1918年，塔尔琴（تار）与“拉迪夫”（ردیف）曲库的大师米尔扎·阿卜杜拉（میرزا عبدالله）在德黑兰去世，学生们按当时的习俗哀悼他：在寿衣上洒玫瑰水，请诵经人到家中诵读《古兰经》，为来客备上哈尔瓦甜糕（حلوا）和椰枣，并在第七天和第四十天（چهلم）聚会追思。而他真正的纪念碑是音乐。学生们一句一句、凭耳朵从他那里学会了拉迪夫，又以同样的方式传了下去。",
  "persians:voyage": "1605年，阿拔斯沙（شاه عباس）把数千名亚美尼亚人从朱勒法（Ջուղա）迁到伊斯法罕，他们在河边建起新区——新朱勒法（نو جلفا）。亚美尼亚商人从那里把波斯丝绸运往世界各地：经陆路到阿勒颇（حلب）和士麦那，经海路到威尼斯和阿姆斯特丹，向东到印度、马尼拉和西藏。他们用亚美尼亚字母写成的账簿里，表亲们从相隔数千公里的港口写信回家，把白银寄回那些满是壁画和金饰的教堂。",
  "persians:quake": "2003年12月26日黎明前，地震袭击了克尔曼（کرمان）沙漠中的巴姆（بم）。大多数房屋是泥砖建的，几秒钟内就倒塌了；约26,000人遇难。屹立了数百年的巨大泥砖城堡——巴姆古城（ارگ بم）——化为尘土。救援者从伊朗各地和世界各国赶来，人们用双手刨开瓦砾。幸存者重新种下椰枣树，城堡的墙壁正在一砖一砖地重建。",
  "achaemenids:hunt": "在如今藏于大英博物馆的圆筒印章上，大流士大帝（𐎭𐎠𐎼𐎹𐎢𐎺𐎢𐏁）站在阿胡拉·马兹达（𐎠𐎢𐎼𐎶𐏀𐎭𐎠）的带翼日轮下的战车上，拉弓射向一头人立而起的狮子。波斯国王在巨大的围墙园林中狩猎，希腊人称之为“乐园”（παράδεισοι）；色诺芬（Ξενοφῶν）描述小居鲁士在凯莱奈（Κελαιναί）骑马追猎野兽，以此磨炼自己和部下。狩猎是国王勇气的证明，也是宫廷的战争学校。",
  "achaemenids:battle": "公元前480年8月，在温泉关（Θερμοπύλαι），薛西斯（𐎧𐏁𐎹𐎠𐎼𐏁𐎠）等了四天，等那支小小的希腊军队撤退。米底人和他自己的“不死军”接连在狭窄的山口被击退，希罗多德（Ἡρόδοτος）说国王三次从宝座上跃起，为部下担忧。后来厄菲阿尔特（Ἐφιάλτης）指出了一条山路，不死军连夜穿过，关口失守。胜利来了，却苦涩而代价高昂。",
  "achaemenids:gather": "在波斯波利斯（𐎱𐎠𐎼𐎿）阿帕达纳宫（𐎠𐎱𐎭𐎠𐎴）的阶梯上，二十三个民族以石刻之姿向国王拾级而上：吕底亚人捧着金碗，巴克特里亚人牵着双峰驼，埃塞俄比亚人扛着象牙，印度人用扁担挑着香料罐。每个使团都被人牵着手引领，平和安详。大流士（𐎭𐎠𐎼𐎹𐎢𐎺𐎢𐏁）希望帝国收成的汇聚看起来像一场万族的节日，而不是一张被征服者的名单。",
  "achaemenids:ritual": "希罗多德（Ἡρόδοτος）说，公元前480年渡过赫勒斯滂（Ἑλλήσποντος）之前的日出时分，薛西斯（𐎧𐏁𐎹𐎠𐎼𐏁𐎠）用金杯把酒倒入海中，向太阳祈祷，愿在抵达欧罗巴尽头之前无物能阻挡他。随后他把杯子、一只金碗和一把波斯剑抛入水中。桥上铺满桃金娘枝，香火燃起，大军静静等待众神的回应。",
  "achaemenids:rain": "想象：帕尔萨（𐎱𐎠𐎼𐎿）的一个旱年，村民们站在灌渠边，望着山上有没有云。城里，一名书吏在泥板上记下口粮配给，这些泥板将保存2,500年。波斯波利斯的台基上刻着大流士本人的祈祷：愿阿胡拉·马兹达（𐎠𐎢𐎼𐎶𐏀𐎭𐎠）保佑这片土地免遭敌军、饥荒与谎言。人人都盼着第二个愿望先被听见。",
  "achaemenids:flood": "希罗多德（Ἡρόδοτος）讲述，居鲁士（𐎤𐎢𐎽𐎢𐏁）进军巴比伦（𒆍𒀭𒊏𒆠）时，他的一匹神圣白马在金德斯河（Γύνδης）中被冲走淹死。居鲁士大怒，让军队花了整整一个夏天挖了360条水渠，直到一个女人过河连膝盖都不会沾湿。随后在公元前539年，他让幼发拉底河本身改道，士兵们沿着河床走进了巴比伦。",
  "achaemenids:wind": "公元前524年，冈比西斯（𐎣𐎲𐎢𐎪𐎡𐎹）从底比斯派出五万人穿越西部沙漠，前往锡瓦的阿蒙（𓇋𓏠𓈖）神谕所。希罗多德（Ἡρόδοτος）说，走到半路，正当他们吃午饭时，一阵猛烈的南风刮起，把他们埋进了沙里。无一人生还。埃及人认为这是神的回答；对波斯家庭来说，那只是一支消失的军队，和一群苦等儿子却再也等不到的母亲。",
  "achaemenids:fire": "公元前330年，亚历山大（Ἀλέξανδρος）放火焚烧了波斯波利斯（𐎱𐎠𐎼𐎿）的宫殿。古代作家说那是在一场醉宴上发生的；另一些人则说那是为雅典（Ἀθῆναι）被焚报仇。从黎巴嫩运来的雪松屋梁燃烧着坠入百柱厅，泥板档案被大火烤得坚硬。对波斯人来说，那是大流士（𐎭𐎠𐎼𐎹𐎢𐎺𐎢𐏁）家族终结的一夜。",
  "achaemenids:thunder": "公元前480年，一支波斯分队进军德尔斐（Δελφοί），想夺取那里的财宝。站在希腊人一边讲述的希罗多德（Ἡρόδοτος）说，当他们抵达雅典娜·普罗奈亚（Ἀθηνᾶ Προναία）神庙时，霹雳从天而降，帕纳索斯山（Παρνασσός）上崩落两块巨岩，压死了许多人，神殿里还传出一声战吼。幸存者四散而逃。无论真相如何，士兵们都明白，山间的风暴可能比任何国王都强大。",
  "achaemenids:birth": "希罗多德（Ἡρόδοτος）讲述，米底国王阿斯提阿格斯梦见外孙将推翻自己，便下令杀死这个新生儿。他的管家哈尔帕哥斯把婴儿交给牧人米特拉达特斯，而牧人的妻子斯帕科刚刚产下一个死胎。她恳求留下这个活着的孩子，改把死婴弃于野外。这个在牛群中长大的男孩就是居鲁士（𐎤𐎢𐎽𐎢𐏁），他将建立世界前所未见的最大帝国。",
  "achaemenids:death": "约公元前530年，居鲁士大帝（𐎤𐎢𐎽𐎢𐏁）被安放在帕萨尔加德（Πασαργάδαι）一座阶梯式基座上的小石屋里，躺在金棺之中。阿里安（Ἀρριανός）说，有麻葛祭司守护陵墓，每天领一只羊、每月领一匹马为他献祭。普鲁塔克（Πλούταρχος）记下了墓铭：世人啊，我是居鲁士，为波斯人赢得了帝国；请不要吝惜这一小块覆盖我身体的土地。亚历山大（Ἀλέξανδρος）发现陵墓遭劫，深为动容。",
  "saracens:hunt": "12世纪奥龙特斯河（العاصي）畔谢扎尔（شيزر）的埃米尔乌萨马·伊本·蒙基兹（أسامة بن منقذ），深情地写到父亲的狩猎：腕上架着游隼和猎隼，马鞍后驮着猎豹，萨路基猎犬在平原上追捕瞪羚和野兔。父亲叫得出每只鹰的名字，记下每一次猎获。年老时，乌萨马把那些清晨回忆为他戎马一生中最快乐的日子。",
  "saracens:battle": "636年8月，在雅尔穆克河（اليرموك）畔，哈立德·伊本·瓦利德（خالد بن الوليد）统率的阿拉伯军队在酷热与尘土中与拜占庭大军对峙了六天。当阿拉伯阵线向营地退缩时，营中的妇女——其中有欣德·宾特·乌特巴（هند بنت عتبة）——用帐篷杆抽打后撤的男人，把他们赶回战场。最后一天，拜占庭军被困在拉卡德谷（وادي الرقاد）的峡谷中，叙利亚归于伊斯兰。",
  "saracens:gather": "夏末，椰枣收获季来到麦地那（المدينة）和哈萨（الأحساء）的绿洲。攀树人系着绳带爬上椰枣树，割下沉甸甸的果串，放给树下等候的人，孩子们则捡拾落果。椰枣晒干后压进皮囊，供商队整个冬天食用。在一片几乎别无所出的土地上，好收成意味着能款待客人，无人挨饿。",
  "saracens:ritual": "出行、婚嫁或出征之前，穆斯林不问卜吉凶，而是做“求选礼拜”（استخارة）。礼两拜，然后念先知所教的祈祷词：主啊，我凭你的知识求你为我抉择；若此事有益于我的信仰、我的今生与归宿，便让它对我容易；若它有害，便让它远离我。然后他入睡，接受即将到来的一切。",
  "saracens:rain": "638年是“灰烬之年”（عام الرمادة），旱灾和饥荒重创阿拉伯半岛，沙尘暴把大地染成灰色。哈里发欧麦尔·伊本·哈塔卜（عمر بن الخطاب）出城举行求雨拜（استسقاء），牵着先知年迈的叔父阿巴斯（العباس）的手，哭着祈求宽恕。传述说，他们还没离开那里，云就聚起来了，人们在数月来的第一场雨中跑回家去。",
  "saracens:wind": "627年壕沟之战（غزوة الخندق）时，一万联军围困麦地那（المدينة）数周之久。后来在一个冬夜，一阵猛烈刺骨的寒风扫过他们的营地，掀翻锅灶，吹灭火堆，刮散帐篷。他们的首领阿布·苏富扬（أبو سفيان）骑上骆驼，下令撤退。《古兰经》（القرآن）记述此事：我曾派遣暴风和你们看不见的军队去攻击他们。对麦地那而言，那风是恩典。",
  "saracens:fire": "在伊斯兰以前的阿拉伯山丘上，慷慨的人会点起“待客之火”（نار القرى），好让夜里迷路的旅人望见，前来用餐。几百年来被称颂为阿拉伯人中最慷慨者的哈蒂姆·塔伊（حاتم الطائي），据说曾对他的奴仆说：把火点得高高的，若它引来一位客人，你就自由了。在沙漠里，山头的一堆火意味着生命。",
  "saracens:thunder": "《古兰经》（القرآن）说：雷霆赞颂他的美德，众天使也因畏惧他而赞颂他。沙漠中的阿拉伯人渴望地望着远方的闪电（برق），因为那意味着某处正在下雨。乌姆鲁勒·盖斯（امرؤ القيس）的《悬诗》（المعلقة）便以夜观这样一场风暴作结：闪电如修士手中的灯，暴雨连根拔起树木，倾泻在盖坦（قطن）的山丘上，直到山谷流成河。",
  "saracens:birth": "穆斯林孩子出生时，父亲在婴儿右耳边低声念宣礼词，让孩子听到的第一句话是“真主至大”。一位虔诚的人嚼一颗椰枣，抹在婴儿的上腭上，称为“塔赫尼克”（تحنيك）。第七天剃去胎发，按头发重量施舍等量的白银给穷人，并宰一只羊作“阿吉卡”（عقيقة）。没人知道这孩子将来会成为什么样的人；人人都祈祷他会成为好人。",
  "saracens:death": "伊斯兰的葬礼没有音乐。遗体被清洗奇数次，裹上素白的布，尽快抬走——可能的话当天下葬——由男人们轮流抬着灵床。殡礼站着进行，不鞠躬。坟墓中，遗体右侧卧，面朝麦加（مكة）。大声哭嚎是不被鼓励的，默默流泪则无妨。身经百战、遍体伤痕的哈立德·伊本·瓦利德（خالد بن الوليد）在霍姆斯（حمص）死于床上，他哭着说自己没能作为烈士而死。",
  "abbasids:hunt": "萨迈拉（سامراء）的阿拔斯哈里发们拥有巨大的围墙猎苑“海尔”（الحير），里面养着瞪羚、野驴和狮子。他们出猎时，马鞍后的软垫上卧着猎豹，戴手套的拳头上架着猎隼，身旁跟着长腿的萨路基猎犬。巴格达（بغداد）最机智的诗人阿布·努瓦斯（أبو نواس）为此创立了一整个诗体——“狩猎诗”（طرديات），赞美猎犬的速度和猎隼的眼睛，深情不亚于赞美美酒。",
  "abbasids:battle": "837年，拜占庭袭掠者洗劫了边境小城扎佩特拉（زبطرة），据说一名被俘的穆斯林妇女呼喊道：穆尔台绥姆啊！哈里发听说后，发誓要回应她。占星家警告说星象不利出征，但838年8月，穆尔台绥姆（المعتصم）攻克了拜占庭皇帝的祖城阿莫里乌姆（عمورية）。艾布·泰马姆（أبو تمام）在一首著名的颂诗中庆贺此事：刀剑比书本更真实。",
  "abbasids:gather": "巴格达（بغداد）周围是萨瓦德（السواد）——两河之间运河纵横的黑土地。阿拔斯时代，农民在这里种植小麦和大麦、椰枣、稻米、甘蔗、棉花，以及从印度和波斯引进的柠檬。收获时，税吏丈量土地税（خراج），驳船沿运河把粮食运往圆城（المدينة المدورة）。伊本·瓦赫希亚（ابن وحشية）的《纳巴泰农书》（الفلاحة النبطية）记录了他们的技艺，自豪于这片古老的土地仍在养活一个帝国。",
  "abbasids:ritual": "曼苏尔（المنصور）在底格里斯河（دجلة）畔选定巴格达（بغداد）城址时，并没有草率动工。宫廷占星家瑙巴赫特（نوبخت）和马沙阿拉（ما شاء الله）推算出吉时，762年7月30日，伴着祈祷砌下了第一块砖。哈里发用灰线描出圆城的城墙，夜里点燃它们，好看清城市的布局。他把它命名为“和平之城”（مدينة السلام）。",
  "abbasids:rain": "一个著名的故事说，哈伦·拉希德（هارون الرشيد）有一次抬头望着一片飘过的云，对它说：你想在哪里下雨就在哪里下吧，你的收成终归会回到我这里。这是在夸耀哈里发国从北非到中亚的广阔疆域。但底格里斯河（دجلة）沿岸的农民知道，没有哪位哈里发能号令天空；旱冬时节，他们和所有人一样聚在清真寺里求雨。",
  "abbasids:flood": "巴格达（بغداد）位于两河之间，也为此付出了代价。伊本·焦齐（ابن الجوزي）等编年史家年复一年地记录：春天底格里斯河（دجلة）上涨，冲破堤岸灌入城中，泥砖房屋倒塌，墓地被淹，市场变成湖泊。人们把家人背上屋顶，祈祷。每一次水退之后，他们都在原地重建，因为那里仍然是巴格达。",
  "abbasids:wind": "想象：一个夏日午后，一场沙尘暴从西部沙漠滚滚而来。巴格达（بغداد）的天空先变黄，再变红，然后暗如黑夜。卡尔赫（الكرخ）市场的商人拉上店铺的护板，底格里斯河（دجلة）上的船夫系好船，智慧宫（بيت الحكمة）里的学者用布盖住手稿。风暴过去后，一切都蒙上一层细尘，宣礼员照常呼唤礼拜，仿佛什么也没发生。",
  "abbasids:fire": "1258年2月，旭烈兀（Хүлэгү）的蒙古大军攻入巴格达（بغداد）。城市燃烧了好几天。哈里发穆斯台绥姆（المستعصم）被杀，包括智慧宫（بيت الحكمة）在内的大图书馆被毁；编年史家说，扔进底格里斯河（دجلة）的书多到河水先被墨汁染黑，又被鲜血染红。对各地的穆斯林而言，这是一个延续了五百年的世界的终结。",
  "abbasids:thunder": "想象：一场冬季风暴降临巴格达（بغداد）。雷声滚过一座座穹顶，一位学者家的孩子们害怕地跑到他身边。他告诉他们铿迪（الكندي）写过的道理：雷电来自云中蒸汽的相撞；然后又加上每个孩子都知道的那句经文：雷霆赞颂他的美德。科学与祈祷并肩而坐，孩子们伴着雨声睡着了。",
  "abbasids:birth": "786年9月的同一个夜晚，哈里发哈迪（الهادي）去世，他的弟弟哈伦·拉希德（هارون الرشيد）成为哈里发，哈伦的儿子阿卜杜拉——即后来的马蒙（المأمون）——降生。巴格达（بغداد）称之为“三位哈里发之夜”。那一夜出生的孩子似乎注定蒙福。然而多年后，他将与同父异母的兄弟艾敏（الأمين）打一场内战，也将开创伊斯兰最伟大的科学时代。",
  "abbasids:death": "809年，哈伦·拉希德（هارون الرشيد）在呼罗珊（خراسان）图斯（طوس）附近的征途中病倒。他知道自己将死，便让人在那里的一座花园里挖好坟墓，俯视着墓穴说：亚当的子孙啊，这就是你的归宿。他由儿子萨利赫清洗、裹尸、主持殡礼，按穆斯林的习俗迅速下葬，没有音乐。《一千零一夜》（ألف ليلة وليلة）里的那位哈里发，长眠在远离巴格达（بغداد）的一座简朴坟墓里。",
  "ayyubids:hunt": "想象：在大马士革（دمشق）城外绿意葱茏的古塔（الغوطة），一位年轻的阿尤布王子黎明时分与鹰师们骑马出猎。一只猎隼离开手套，盘旋而上，然后向巴拉达河（بردى）上空的一只鹤俯冲。老猎手称赞的是鸟，而不是王子。中午他们带着鹤和野兔回来，作为晚餐，王子的叔叔提醒他：打猎只是为与法兰克人作战而练习。",
  "ayyubids:battle": "1187年7月4日，在加利利海（بحيرة طبريا）上方的哈丁角（قرون حطين），萨拉丁（صلاح الدين）把断水的十字军困住。他的士兵点燃干草，让浓烟扑向口渴的骑士们的脸。真十字架被夺，居伊国王投降。在帐篷里，萨拉丁递给居伊一杯冰镇玫瑰水；居伊又把它递给沙蒂永的雷纳德（Renaud de Châtillon）时，萨拉丁说：这杯不是我给他的。",
  "ayyubids:gather": "在大马士革（دمشق）周围的果园绿洲古塔（الغوطة），杏子在初夏成熟。一家人爬上树采摘，果子在屋顶上摊成薄片晒干，做成杏皮（قمر الدين），销往阿尤布王朝各地。在埃及，甘蔗被砍下，送进苏丹的磨坊榨汁。在萨拉丁（صلاح الدين）的继承者治下，与法兰克人的和平让收成与贸易得以兴旺。",
  "ayyubids:ritual": "萨拉丁（صلاح الدين）的法官兼传记作者巴哈丁·伊本·沙达德（بهاء الدين بن شداد）写道，苏丹喜欢在星期五、在聚礼的时刻开战，这样每座清真寺的宣教者都会在穆斯林军队与敌人交锋的那一刻为他们祈祷。每次交战前他都亲自礼拜，从不问占星家。他相信，答案只属于真主。",
  "ayyubids:rain": "想象：大马士革（دمشق）的一个旱冬，巴拉达河（بردى）在两岸之间低低地流着。人们走出城外，来到礼拜场（مصلى），穿着旧衣，谦卑恭顺，老人和孩子也一同前往。伊玛目带领求雨拜，并把斗篷翻过来穿，像先知当年那样，希望天空也随之翻转。回家路上，一阵风带来了湿尘土的气味。",
  "ayyubids:flood": "1221年，第五次十字军的军队从杜姆亚特（دمياط）沿尼罗河（النيل）向开罗（القاهرة）进军，正赶上一年一度的洪水上涨。苏丹卡米勒（الكامل）放他们过去，然后下令掘开他们身后的堤坝。洪水包围了十字军营地，把他们的道路变成了沼泽。饥饿被困的十字军交出杜姆亚特，换取安全撤离。是尼罗河自己为埃及而战。",
  "ayyubids:wind": "想象：春天，喀新风（خماسين）从西部沙漠吹进开罗（القاهرة），一股裹挟着沙粒的热风。萨拉丁（صلاح الدين）在穆盖塔姆山（المقطم）上修建的城堡上空变成橙色。马穆鲁克卫兵裹住脸，骆驼背对着风跪下，经学院里的学生们在昏暗中无法读书。老人们说它要刮五十天，但明天也许就会放晴。",
  "ayyubids:fire": "1190年围攻阿卡（عكا）时，十字军造了三座巨大的攻城塔，任何火都烧不着。伊本·沙达德（ابن شداد）讲述，一个来自大马士革（دمشق）的年轻铜匠献上了他调配的石脑油与其他物质的混合物。他向一座塔扔出一罐：毫无动静。再扔一罐，塔燃起了火焰，接着是下一座。城墙上的穆斯林欢呼雀跃；萨拉丁（صلاح الدين）想重赏他，他却拒绝了。",
  "ayyubids:thunder": "想象：冬天，一场雷暴降临阿卡（عكا）城外的阿尤布营地。帐篷倒塌，马匹嘶鸣，壕沟灌满了水。发着高烧的萨拉丁（صلاح الدين）在士兵中间走动，确认他们都有地方避雨。原野对面，十字军营地的情形更糟。两支军队听着同样的雷声，两边都有人祈祷：愿围城在自己倒下之前结束。",
  "ayyubids:birth": "萨拉丁（صلاح الدين）于1137或1138年生于提克里特（تكريت），恰在那一夜，他的父亲阿尤布（أيوب）和叔父希尔库（شيركوه）因希尔库杀了人而被迫逃离该城。阿尤布认为这孩子带来了厄运，不想理会他。他的一个手下回答说：你不知道，这孩子也许会成为一位伟大而著名的君王。五十年后，他夺回了耶路撒冷（القدس）。",
  "ayyubids:death": "1193年3月4日，萨拉丁（صلاح الدين）在发烧十二天后于大马士革（دمشق）去世。伊本·沙达德（ابن شداد）写道，国库里只剩四十七枚迪尔汗和一枚金币；他把一切都施舍了出去，连葬礼的钱都得借。他被清洗、裹尸，举行殡礼，当天下午便下葬。没有音乐，只有一座城市的哭声——人们觉得自己失去了一位父亲。",
  "turks:hunt": "马利克沙（ملکشاه）是11世纪七八十年代统治从安纳托利亚到中亚的塞尔柱苏丹，他爱狩猎胜过一切。编年史家说，他清点自己的猎获，每猎一头就施舍穷人一枚金第纳尔，让自己的乐趣以善行来偿付。他在库法（الكوفة）建起一座塔，塔上嵌满他射杀的瞪羚的角和蹄。",
  "turks:battle": "1071年8月26日星期五，在曼齐刻尔特（Malazgirt），苏丹阿尔普·阿尔斯兰（آلپ ارسلان）身着白衣与军队一同礼拜，说若他战死，这便是他的寿衣。他亲手扎起坐骑的尾巴。塞尔柱骑射手先诱拜占庭军向前，然后合围。皇帝罗曼努斯四世（Ῥωμανὸς Διογένης）被俘，阿尔普·阿尔斯兰以礼相待，放他回去。安纳托利亚从此向突厥人敞开。",
  "turks:gather": "每年春天，安纳托利亚的土库曼氏族把黑色山羊毛帐篷迁上“亚伊拉”（yayla）——高山夏季牧场。妇女们挤羊奶，做酸奶、奶酪和黄油，编织将在科尼亚出售的打结地毯。秋天他们又带着羊毛、毛毡和干奶酪下山。一年一度的迁徙就是收获，古老的乌古斯（Oğuz）歌谣随之上山下山。",
  "turks:ritual": "拜占庭史家米南德（Μένανδρος）记述6世纪60年代的突厥人时说，他们敬重火、水与土，但只崇拜天地的创造者腾格里（𐱅𐰭𐰼𐰃），向他献祭马、牛和羊。他们的萨满“卡姆”（kam）预言未来。鄂尔浑碑文上，可汗们说自己能统治是因为腾格里的意志，而当百姓忘记他时，便迷失了。",
  "turks:rain": "古代突厥诸民族知道“雅达石”（yada taş），即求雨石。求雨师“雅达奇”把石头浸入水中并吟诵，召唤云、雪或风暴。马哈茂德·喀什噶里（محمود الكاشغري）在1072年写道，他亲眼见过：一个人用这样一块石头在夏天招来雪和雨，扑灭了一场火。对干旱草原上的牧人来说，这是最珍贵的法术。",
  "turks:flood": "想象：春天，托罗斯山（Toros）上的雪融化了，土库曼村庄下面的河水狂奔，浑黄咆哮。洪水冲走了一座磨坊和一群羊，男人们拿着绳子站在岸边，无能为力。老婆婆说今年河神饿了。傍晚，他们煮了一只羊羔，与全村分享，求个好运。",
  "turks:wind": "想象：夏末，一场沙尘暴横扫科尼亚平原。商队停在苏丹汉——塞尔柱苏丹凯库巴德（کیقباد）于1229年修建的巨大石砌商队驿站。骆驼被牵进雕花大门，商人们挤进拱顶大厅，铁门关上。外面狂风呼啸了好几个小时。里面，有人讲起《先祖科尔库特书》的故事，直到风暴过去。",
  "turks:fire": "569年，拜占庭使节泽马库斯（Ζήμαρχος）抵达阿尔泰山中突厥可汗室点密的宫廷。米南德（Μένανδρος）记载，在他获准入内之前，突厥萨满在他的行李上方击鼓摇铃，捧着燃烧的乳香绕他而行，并让他从两堆火之间走过，为他驱除邪祟。对古代突厥人来说，火能净化一切来自外面的东西。",
  "turks:thunder": "想象：在开阔的草原上，牧人先看见风暴，后听见雷声。古代突厥人相信雷是腾格里（𐱅𐰭𐰼𐰃）的声音，闪电劈向不洁之物所在之处。树木或帐篷被雷击中时，人们便不再碰那个地方，并献上供品。他把马匹聚拢、拴好，徒步等待，在无边的天空下显得那么渺小，直到雨水落下。",
  "turks:birth": "古代突厥的母亲们呼唤乌迈（𐰆𐰢𐰖），掌管生育与孩童的女神。阙特勤（𐰚𐰇𐰠𐱅𐰃𐰏𐰤）的鄂尔浑碑文说，他的母亲如同乌迈。在毡房里，临产的女人抓着从顶架上垂下的绳子，接生婆和家中女眷在旁相助；胎盘被小心地埋起来，因为人们相信乌迈守护着它。然后孩子被取了名字，全族都在猜想他将来会成为怎样的人。",
  "turks:death": "中国史书描述过突厥的葬礼。遗体停放在帐中，亲属骑马绕帐七圈，哭喊着用刀割面，血泪俱下。择定吉日，死者连同他的马匹和财物一起火化，墓上立起石像，还有一排石头“杀人石”（balbal），每块代表他杀死的一个敌人。731年，阙特勤（𐰚𐰇𐰠𐱅𐰃𐰏𐰤）就是这样被哀悼的。",
  "ottomans:hunt": "1648年至1687年在位的苏丹穆罕默德四世（محمد رابع）沉迷于狩猎，被称为“猎人”（آوجی）。他从埃迪尔内（ادرنه）的宫殿出发，一去就是数周，成千上万的村民被命令在森林中驱赶，把鹿、野猪和狼赶向他。朝臣们抱怨帝国的战争节节失利，他却在打猎；苏丹回答说，狩猎让他保持骑马作战的体力。",
  "ottomans:battle": "1453年5月29日黎明前，穆罕默德二世（محمد ثانی）对君士坦丁堡（قسطنطنیه）发起最后总攻。军乐队（مهتر）在阵线后不停演奏，定音鼓和苏尔奈管不间断地鸣响，让士兵们不至丧失斗志。几周前，他的战船已被拖上涂油的圆木，从陆路运进了金角湾（Haliç）。当禁卫军（Yeniçeri）在圣罗曼努斯门附近突破城防时，这座千年之城陷落了。苏丹当时二十一岁。",
  "ottomans:gather": "每年六月，布尔萨（بورسه）乡间的蚕茧收获上市。农民们用麻袋把蚕茧运到巴耶济德二世（بایزید ثانی）于1491年建造的“蚕茧客栈”（Koza Han），来自波斯、意大利和帝国各地的商人在院中小清真寺四周讨价还价。蚕茧煮过、缫成丝，织成供奥斯曼宫廷穿戴的天鹅绒和锦缎。",
  "ottomans:ritual": "苏丹出征时，据说曾属于先知的圣旗（سنجاق شریف）会从托普卡帕宫（Topkapı Sarayı）的箱子中请出。人们诵读《古兰经》（قرآن），乌莱玛们祈祷，苏丹或大维齐尔含泪接过圣旗并亲吻它。圣旗被举在大军最前方。穆斯林不向算命人询问战事；他们向真主祈求，并接受他的答复。",
  "ottomans:rain": "干旱的年份里，伊斯坦布尔（استانبول）的百姓登上金角湾（Haliç）上方奥克广场（Okmeydanı）的露天礼拜场。学者、工匠、孩子甚至牲畜都被带去，因为穆斯林相信，真主也许会看在无辜者的份上施恩。他们做求雨祷告（yağmur duası），宣教者劝众人还清债务、彼此和解。艾弗利亚·切莱比（Evliya Çelebi）描述过这些人群满怀希望地走回家去。",
  "ottomans:flood": "1563年9月，一场突如其来的洪水冲下伊斯坦布尔（استانبول）以北的山谷，席卷卡厄特哈内（Kâğıthane）溪，摧毁了向城市输水的部分渡槽。房屋和磨坊被冲走，许多人溺亡。苏莱曼大帝（سلیمان قانونی）命令建筑师米马尔·锡南（معمار سنان）重建克尔克切什梅（Kırkçeşme）供水系统，锡南在山谷间架起巨大的石砌渡槽，有些至今仍然矗立。",
  "ottomans:wind": "1541年10月，皇帝查理五世率大军在阿尔及尔（الجزائر）城外登陆，替奥斯曼苏丹守城的是哈桑阿迦（حسن آغا）。随后一场可怕的风暴从海上袭来。雨水浸透了西班牙人的火药，一百五十多艘船被刮上岸撞毁。守军出城突击，皇帝只得扬帆离去。在阿尔及尔，人们把这场风暴铭记为真主对信众的援助。",
  "ottomans:fire": "伊斯坦布尔（استانبول）是一座木屋之城，最怕听到那声呼喊：“着火了”（yangın var）。1660年7月，大火从埃米诺努（Eminönü）附近燃起，烧了好几天，毁掉了大半座城市：清真寺、市场和数以万计的民居。苏丹的母亲图尔汗·哈蒂杰利用废墟，完成了海边的新清真寺（Yeni Cami）。后来，消防员（tulumbacı）们扛着水泵在街上奔跑救火。",
  "ottomans:thunder": "想象：一场夏日风暴砸向博斯普鲁斯海峡（Boğaziçi）。闪电击中于斯屈达尔（Üsküdar）附近的海面，渔民们拼命往岸边划。在托普卡帕宫（Topkapı），宫廷学校的侍童们停下书法课，望向海面。他们的老教师一言不发，只是写完手中那个字母，然后为海上的人念了一段祈祷。雷声渐远，课继续上。",
  "ottomans:birth": "苏丹得子时，托普卡帕宫（Topkapı）鸣炮，伊斯坦布尔（استانبول）张灯结彩好几天，人群欢呼。但人人都知道当王子意味着什么。根据兄弟相残法，1595年穆罕默德三世（محمد ثالث）即位时，他的十九个兄弟被绞死。王子的诞生是王朝的希望，也是王朝的恐惧；他的母亲既祈祷他能登基，也祈祷他能活下去。",
  "ottomans:death": "1566年9月，苏莱曼大帝（سلیمان قانونی）在围攻锡盖特堡（Szigetvár）时死于营帐中。大维齐尔索科卢·穆罕默德帕夏（Sokollu Mehmed Paşa）隐瞒死讯数周，以免军心动摇，直到新苏丹的地位稳固。遗体被运回国，清洗、裹尸，在苏莱曼尼耶清真寺（Süleymaniye Camii）举行殡礼，然后安放在陵墓中。与所有穆斯林葬礼一样，没有音乐，只有诵经与祈祷。",
  "armenians:hunt": "摩西·霍列纳齐（Մովսես Խորենացի）讲述了被临终的父亲诅咒的国王阿尔塔瓦兹德（Արտավազդ）。一天，他在马西斯山（Մասիս）——即阿拉拉特山（Արարատ）——的山坡上打猎时突然发狂，连人带马坠入深渊，就此消失。亚美尼亚村民说他被锁在一个洞穴里，有狗守着，不停地舔他的锁链，把锁链舔得越来越细；铁匠们每个星期天都敲击铁砧，好让他继续被锁住。狩猎成了一则警世故事。",
  "armenians:battle": "451年5月26日，在阿瓦雷尔（Ավարայր），瓦尔丹·马米科尼扬（Վարդան Մամիկոնյան）率领亚美尼亚人迎战要求他们放弃基督教的萨珊波斯人。亚美尼亚人战败，瓦尔丹与许多同伴阵亡。然而抵抗仍在继续，直到484年波斯在努瓦尔萨克（Նվարսակ）条约中准许宗教自由。教会每年在“瓦尔达南克节”（Վարդանանք）纪念他们：一场败仗，被铭记为良知的胜利。",
  "armenians:gather": "亚美尼亚人说，方舟停靠后，挪亚（Նոյ）在阿拉拉特山（Արարատ）下种下了第一片葡萄园。考古学家在阿列尼-1（Արենի）洞穴中发现了一座有六千多年历史的酿酒作坊，有压榨池和储酒罐。每年秋天，葡萄收获照旧来临：一家人在梯田上剪下葡萄，压榨，为第一批酒祝福。在圣母升天节，葡萄要先在教堂里受祝福，然后才有人吃。",
  "armenians:ritual": "亚美尼亚教会保留着“马塔赫”（մատաղ）——为病人、亡者或即将远行的人献上一只羊羔或公鸡。神父为盐祝福，让牲畜吃下盐，然后宰杀，把肉分给穷人和邻居。祭坛上不焚烧任何东西；献祭就是分享的这顿饭，以及祈求上帝善待未来的祷告。",
  "armenians:rain": "盛夏，当阿拉拉特（Արարատ）平原的田地干裂时，亚美尼亚人庆祝“瓦尔达瓦尔节”（Վարդավառ）。它曾经祭祀女神阿斯蒂希克（Աստղիկ）；如今是主显圣容节。人们在街上互相泼一桶桶的水，孩子们伏击大人，谁也不能生气。这是欢笑，也是一个古老的愿望：愿天空也这样做，愿雨在麦子枯死之前到来。",
  "armenians:wind": "公元前401年冬，色诺芬（Ξενοφῶν）率领的希腊军队在凛冽的北风中翻越亚美尼亚高原，积雪深厚，士兵们的脚趾冻掉了。他们向风献祭。后来他们找到了亚美尼亚的村庄，那里的房屋挖在地下，一家人与山羊和母牛住在一起，用麦秆吸饮大麦啤酒招待客人。村民们早就学会了如何熬过这样的风暴。",
  "armenians:fire": "二月的特仁德兹节（Տրնդեզ），亚美尼亚人用教堂里祝福过的蜡烛，在教堂院子里点起一大堆篝火。新婚夫妇手拉手跳过火堆，然后是盼着结婚的年轻人，再然后是所有人；想要孩子的妇女绕着火堆行走。灰烬撒在田里，祈求丰产。在这里，火意味着冬去之后温暖的回归，以及春天即将到来的许诺。",
  "armenians:thunder": "在古老的亚美尼亚信仰中，瓦哈根（Վահագն）是雷电与战争之神，是屠龙者（Վիշապաքաղ）。当闪电劈开山间的夏日天空，那是瓦哈根在击打“维沙普”（վիշապներ）——吞下雨水藏进云中的恶龙。石刻的龙鱼“维沙帕卡尔”（վիշապաքար）至今仍立在高原的泉水旁。雷声虽可怕，却意味着水正被释放。",
  "armenians:birth": "摩西·霍列纳齐（Մովսես Խորենացի）保存了一首曾伴着里拉琴吟唱的古歌：天与地在分娩，紫色的海在分娩，海中一根小小的红芦苇也在分娩。芦苇茎中冒出烟，烟中生出火焰，火焰中跑出一个小男孩，头发是火，胡须是焰，双眼是太阳。那是瓦哈根（Վահագն）的诞生，也是亚美尼亚人所有希望的诞生。",
  "armenians:death": "亚美尼亚人去世后，家人在家中点着蜡烛守灵一夜；妇女们呼唤着死者的名字唱挽歌。神父主持安魂礼（հոգեհանգիստ），死者面朝东方下葬。几个世纪以来，亚美尼亚人雕刻了十字石（խաչքարեր）——如刺绣般镂空的石十字架，为灵魂祈求救赎。在塞凡湖（Սևանա լիճ）畔的诺拉图斯（Նորատուս），近千块十字石一同立在草丛中。",
  "georgians:hunt": "绍塔·鲁斯塔维利（შოთა რუსთაველი）约1200年为女王塔玛尔（თამარი）所作的《虎皮武士》（ვეფხისტყაოსანი）以一场狩猎开篇。阿拉伯国王罗斯捷万（როსტევანი）与年轻的统帅阿夫坦季尔（ავთანდილი）在平原上比试箭术，仆从们清点每一次猎获，年轻人获胜时国王开怀大笑。随后他们看见一个身披虎皮的陌生人在溪边哭泣，冒险就此开始。格鲁吉亚人至今仍背诵它的诗句。",
  "georgians:battle": "1121年8月12日，在迪德戈里（დიდგორი），建设者大卫四世（დავით აღმაშენებელი）迎战规模大得多的塞尔柱联军。他改革过军队，他的两百名士兵装作投降骑马上前，随即突袭敌军将领。格鲁吉亚骑兵从山上冲下，联军溃散。格鲁吉亚人称之为“奇迹般的胜利”（ძლევაჲ საკვირველი）。一年后大卫收复第比利斯（თბილისი），黄金时代由此开启。",
  "georgians:gather": "每年秋天是“尔特韦利”（რთველი），即葡萄收获节。卡赫季（კახეთი）的整村人一起走进葡萄园；葡萄在木槽中踩踏，汁液、果皮和果梗一起倒进“克韦夫里”（ქვევრი）——埋在土中的巨大陶罐，密封发酵到来年春天。之后是“苏普拉”（სუფრა）盛宴，由祝酒主持人“塔马达”（თამადა）主持，三声部的歌声一直响到深夜。",
  "georgians:ritual": "在赫夫苏列季（ხევსურეთი）山区，每个社区都有自己的“哈季”（ხატი）圣所，由从村中长老里选出的祭司“赫维斯贝里”（ხევისბერი）主持。节日里，他酿造圣啤酒，宰羊，代表众人向圣所的神圣守护者祷告。有时一位先知“卡达吉”（კადაგი）陷入恍惚，说出神灵对来年的旨意。人们静静聆听，男人在一边，女人站在远处。",
  "georgians:rain": "在格鲁吉亚乡村，遇到旱灾时，孩子们用一根木棍裹上破布做成玩偶，叫“拉扎雷”（ლაზარე）或“贡贾”（გონჯა），抬着它挨家挨户地唱：拉扎雷，给我们雨吧。每家往玩偶身上泼水，给孩子们鸡蛋、面粉或奶酪。然后玩偶被扔进河里。这是游戏，也是一群靠天吃饭的人真诚的祈祷。",
  "georgians:flood": "想象：春天，里奥尼河（რიონი）——科尔基斯（Κολχίς）古时的法西斯河（Φᾶσις）——因高加索的融雪而上涨。河水漫过低地的田野，伊梅列季（იმერეთი）的农民们在架在木桩上的木屋里观望。他们向圣乔治（წმინდა გიორგი）祈祷，然后等待。河水退去时留下新鲜的淤泥，玉米会长得很高。洪水夺走，也给予。",
  "georgians:wind": "想象：一场冬季风暴越过山口，进入上斯瓦涅季（ზემო სვანეთი）。大雪横飞，狂风在峡谷中呼啸。每户斯瓦恩人家都爬进自家的石塔——那是一千年前为防御敌人、雪崩和血仇而建的。塔上，在一小堆火旁，祖父和儿子们用三个声部唱起一首缓慢的歌，外面的风也成了和声的一部分。",
  "georgians:fire": "1795年9月，波斯沙阿阿迦·穆罕默德汗（آغا محمدخان）在克尔察尼西（კრწანისი）击败了弱小的格鲁吉亚军队，进入第比利斯（თბილისი）。城市被焚烧劫掠了好几天；教堂被毁，数千人被掳走。七十五岁的国王埃雷克勒二世（ერეკლე II）是被孙子硬拖下战场的。格鲁吉亚人铭记着在战场上战斗到最后的三百名阿拉格维勇士（არაგველები）。",
  "georgians:thunder": "在斯瓦涅季（სვანეთი）山区，闪电属于先知以利亚（ელია）。有人被雷劈死时，斯瓦恩人不按通常的方式哀悼，因为死者是被上帝选中的。他们围着遗体慢慢转圈起舞，唱着献给以利亚的古老颂歌《以利亚·勒尔德》（Elia lrde），求他饶过生者。高山河谷中的雷声神圣、可怕，近在咫尺。",
  "georgians:birth": "在大高加索山区，赫夫苏尔（ხევსური）和普沙维的女人在村外一间单独的小屋“萨姆列夫洛”（samrevlo）里分娩，因为生育被认为对圣所不洁。她们常常独自或只有一个帮手陪着生产。这很危险，许多人因此丧命。然而孩子回到家时，全家会在“苏普拉”（სუფრა）宴席上为他祝酒：愿你做个好格鲁吉亚人，愿你给我们的人民带来好运。",
  "georgians:death": "斯瓦涅季（სვანეთი）有人去世时，全村聚集唱“扎里”（ზარი）——葬礼挽歌：男人们以三个声部唱出缓慢而粗粝的“啊”和“哇伊”的呼喊，几乎没有歌词，有人认为这声音比基督教还要古老。女人们坐在遗体旁，呼唤着死者的名字哀哭。下葬之后是“克列希”（ქელეხი）追思宴，为死者和迎接他的祖先们举杯。",
  "huns:hunt": "约达尼斯（Iordanes）讲过一个匈人西迁的古老故事。迈奥提斯沼泽——即亚速海——彼岸的猎人们追逐一头母鹿，它不时停下回头张望。它引着他们穿过一片无人知道能涉过的浅滩，随后消失了。对岸便是斯基泰（Σκυθία），富饶而开阔。猎人们骑马回去召集族人，草原的新时代由此开始。",
  "huns:battle": "452年，阿提拉长久围困意大利北部的阿奎莱亚，部下开始抱怨，想要离去。普里斯库斯（Πρίσκος）和约达尼斯说，这时阿提拉看见在城中屋顶筑巢的鹳鸟正把幼鸟带往乡间。他对军队说：看，鸟儿都知道这座城要陷落了。匈人士气大振，推上攻城器械，阿奎莱亚被攻陷并毁灭。",
  "huns:gather": "449年，罗马使节普里斯库斯（Πρίσκος）骑马穿过匈人领地前往阿提拉的宫廷。他写道，在村子里，人们给他们的是小米而不是小麦，还有一种叫“梅多斯”（μέδος）的饮料，即蜂蜜酒，仆从们则喝用大麦酿的“卡莫斯”（κάμος）。在阿提拉的木头大厅里，宾客用银器进餐，阿提拉本人却用木盘吃肉，衣着朴素。汇聚与分享，正是展示权力的方式。",
  "huns:ritual": "约达尼斯（Iordanes）写道，451年卡塔隆平原（Campi Catalaunici）之战前，阿提拉命令占卜者从牛的内脏和刮净的骨头上的纹路中预测未来。他们预言匈人将遭灾祸，但说敌方一位伟大的首领将会阵亡。阿提拉认为这代价值得付出。他出战了，西哥特国王狄奥多里克战死。预言从两方面都应验了。",
  "huns:rain": "想象：潘诺尼亚平原上一个炎热干燥的夏天。草已枯黄，马匹消瘦，畜群必须迁徙去找水。匈人家庭收拾好大车，把牲畜赶向蒂萨河。夜里他们望着西边的天空，看有没有闪电。一位老妇人把一条布系在树上，对着天空低语：孩子们需要雨。",
  "huns:wind": "想象：一场草原风暴从东方滚滚而来。一堵沙尘之墙遮暗了太阳，匈人营地迅速行动：大车围成一圈，毡盖用绳子捆牢，马匹被调转得尾巴迎风。骑手们蒙住脸等待。他们并不害怕；风一向与他们同行，罗马人也说，匈人自己就像风暴一样席卷而来。",
  "huns:fire": "451年卡塔隆平原（Campi Catalaunici）之战后，阿提拉退回车阵围成的营地。约达尼斯（Iordanes）说，他下令用马鞍堆起一座火葬堆，一旦罗马人攻进来，他宁可投身火中，也不愿被敌人俘获或杀死。那堆火始终没有点燃；罗马人和哥特人放他走了。但那些马鞍整夜都备在那里。",
  "huns:thunder": "想象：大平原上，一场雷暴降临匈人营地。马匹跺蹄嘶鸣，闪电劈开河边一棵孤树。萨满们说天神发怒了，必须用马祭来平息。孩子们躲在大车底下数着闪光。到了早上，草又绿了，人们围着火堆把这场风暴当作一个关于力量的故事来讲述。",
  "huns:birth": "449年，普里斯库斯（Πρίσκος）在阿提拉的宴会上注意到，这位对其他人都严厉不苟言笑的国王，却把幼子厄尔纳克（Ἠρνάχ）拉到身边，用温柔的目光看着他，捏他的脸颊。一个匈人解释说：占卜者告诉阿提拉，他的家族将会衰落，却会由这个男孩复兴。每个父亲都盼着孩子能挽救家门；阿提拉被人这样告知过，并且相信了。",
  "huns:death": "453年，阿提拉在新婚之夜死去。约达尼斯（Iordanes）依据普里斯库斯（Πρίσκος）的记载说，他的遗体停放在平原中央的一顶丝绸帐篷里，最好的骑手们绕着帐篷驰骋，唱着颂扬他功业的挽歌“斯特拉瓦”（strava）。他的部下剪去头发，割破脸颊，让这位最伟大的战士不是以泪水而是以鲜血被哀悼。他被秘密安葬在金、银、铁三重棺椁之中。",
  "cumans:hunt": "想象：一位库曼可汗带着鹰师，皮手套上架着一只金雕，驰骋在黑海北岸的草原上。猎犬从针茅丛中惊起一只狐狸，金雕从高空直扑下去，众人欢呼。狩猎让年轻骑手为战争保持敏锐，也让冬天的锅里有肉。在他们身后的一座古坟上，一尊祖先石像注视着平原。",
  "cumans:battle": "1185年，诺夫哥罗德-谢维尔斯基（Новгород-Северский）的伊戈尔王公（Игорь）为博取荣耀，出兵攻打库曼人——即波洛伏齐人（половци）。库曼可汗孔恰克和格扎克聚集战士，在卡亚拉河（Каяла）畔包围了他的军队。断水苦战三天后，罗斯军队覆没，伊戈尔被俘。孔恰克待他如宾客，后来还把女儿嫁给了伊戈尔的儿子。《伊戈尔远征记》（Слово о плъку Игоревѣ）哀叹这场失败；库曼人则在庆祝。",
  "cumans:gather": "想象：初夏，库曼妇女在营地里挤马奶。马驹被拴成一排，好让母马留在附近；马奶倒进皮囊，用木杵连续搅打好几天，直到变成酸而微醺的马奶酒。好年景意味着满囊的马奶酒、肥壮的羊和络绎的访客，短短的夏夜里歌声一直唱到很晚。",
  "cumans:ritual": "1239年，库曼人与拉丁皇帝鲍德温二世（Baudouin II）缔结同盟。让·德·茹安维尔记下了那场仪式：库曼首领们和鲍德温的部下从手上放血滴入杯中，兑上酒和水喝下，发誓从此结为兄弟。然后在他们之间把一条狗劈成两半，发誓谁若背弃誓言，就会被同样劈开。",
  "cumans:rain": "想象：一个干旱的夏天，库曼各氏族聚集在古坟上的一尊石像旁，那是一位双手捧杯于腹前的祖先像。他们把马奶酒浇在石像脚下，在它面前摆上肉，请祖先替他们向腾格里求雨。长老们望着西边的天空。若三天内云来了，就说明供品被接受了。",
  "cumans:wind": "想象：一场冬季暴风雪“布兰”横扫黑海北岸草原，雪大得骑手连自己马头都看不见。库曼人的畜群背对着风随风漂移；牧人们用绳子连在一起跟在后面，唱着歌安抚牲畜。一户人家可能一夜之间损失一半的羊。风雪过去后，大家清点剩下的，然后继续生活。",
  "cumans:fire": "1239年，为躲避蒙古人，科腾汗（Kötöny）率领约四万户库曼人进入匈牙利。1241年，匈牙利贵族怀疑他们替蒙古人刺探，在佩斯杀害了科腾。愤怒的库曼人离开了这个王国，南下保加利亚，一路焚烧身后的村庄。他们走过的路上浓烟升腾。他们觉得自己被曾许诺收留他们的人背叛了。",
  "cumans:thunder": "想象：第聂伯河附近的草原上，一场夏日风暴正在聚集。闪电劈下，一个库曼牧人扑倒在马旁。库曼人相信腾格里在雷声中说话，被闪电击中的地方是被上天触碰过的。事后，这家人会把奶送到烧焦的草地上留在那里，轻声说一句表示敬意的话。",
  "cumans:birth": "1262年，库曼首领之女库曼人伊丽莎白（Kun Erzsébet）生下了匈牙利王位继承人拉斯洛（László）。定居匈牙利的库曼人希望他会成为他们的保护者。他的确如此：当上国王后，他穿库曼人的衣服，与他们一起生活，爱上了一个库曼姑娘，直到1290年被库曼刺客杀害。一个母亲的希望和一个民族的希望，都寄托在一个孩子身上。",
  "cumans:death": "让·德·茹安维尔描述了13世纪40年代在君士坦丁堡（Κωνσταντινούπολις）附近一位库曼骑士的葬礼。人们挖了一个大坑，让死者穿着华服端坐其中。和他一起放进去的还有他最好的马和他的侍从——都是活的——以及金银。可汗赠送厚礼，好让死者以富人的身份抵达另一个世界。然后他们填平坑穴，在上面堆起一座坟丘。",
  "tatars:hunt": "想象：克里米亚草原一个结霜的早晨，一位鞑靼贝伊带着猎犬和一只苍鹰出猎。野兔从枯草中窜出，苍鹰扑击。男人们策马呼喊，贝伊的小儿子用弓射中了他的第一只野兔。今晚会有一场小小的宴席，男孩的祖父会告诉他，他骑马的样子像极了祖先。",
  "tatars:battle": "1552年10月，莫斯科（Москва）的伊凡四世（Иван IV）围攻鞑靼汗国的都城喀山（Казан）。守军在亚德加尔·穆罕默德汗率领下顶着炮火坚守城墙数周。10月2日，俄国工兵在城墙下引爆地雷，攻入城中。清真寺被毁，许多守军死在街头。鞑靼歌谣至今仍铭记着喀山的陷落和库尔·谢里夫清真寺（Кол Шәриф）。",
  "tatars:gather": "犁头节（Сабан туе）标志着伏尔加河（Идел）鞑靼人春播的结束。小伙子们骑马挨家挨户收集礼物：绣花毛巾、头巾、鸡蛋。然后全村人聚到草地上，进行系腰带摔跤、赛马、套袋跑，还有爬涂油的高杆夺奖。活儿干完了，人人都盼着田地会报答这份辛劳。",
  "tatars:ritual": "想象：在喀山（Казан）的一个鞑靼村庄，一个年轻人必须决定要不要去布哈拉（بخارا）求学。他不去找算命人。他沐浴净身，夜里礼两拜，念诵“求选”（استخارة）祈祷词：主啊，若此事有益于我的信仰和生活，便让它对我容易。早上他告诉母亲他要去，母亲开始为他收拾行装。",
  "tatars:rain": "干旱的夏天，鞑靼村庄会举行“求雨”（яңгыр теләү）。人们聚在河边或山丘上，用一口大锅一起煮粥，分给每一个人，然后祈祷。接着大家互相泼水，有时甚至把毛拉轻轻扔进河里。每个人都在笑，但还是都望着天空，盼着祈祷已被听见。",
  "tatars:wind": "想象：一场冬季暴风雪降临伏尔加河（Идел）草原。在鞑靼村子里，风把道路堆满了雪，一直埋到窗户。各家把小牛牵进屋里，祖母点上灯，在房子的吱呀声中朗读一本旧故事书。早上，男人们挖出通往清真寺的雪道，宣礼员照常呼唤晨礼。",
  "tatars:fire": "1571年5月，克里米亚鞑靼可汗德夫列特·格莱（Devlet Geray）一路袭掠直抵莫斯科（Москва）。他的军队到达的当天，郊区起火，大火借着风势席卷了这座木头城市。克里姆林宫（Кремль）的火药库爆炸。编年史家说死者数以万计。对克里米亚鞑靼人来说，这是为喀山（Казан）和阿斯特拉罕复仇；对莫斯科来说，这是一场永难忘怀的浩劫。",
  "tatars:thunder": "922年，伊本·法德兰（ابن فضلان）从巴格达（بغداد）出使伏尔加河（Идел）保加尔人——喀山鞑靼人的祖先。他写道，房屋遭雷击时，保加尔人不肯靠近，而是任由它连同屋里的一切自行毁灭，说那是一座遭了天怒的房子。他还见到了北极光，主人们告诉他，那是信道的精灵和不信道的精灵在天上交战。",
  "tatars:birth": "鞑靼婴儿出生后，亲友邻居聚在一起举行命名礼（исем кушу）。毛拉抱起孩子，面朝麦加（مكة），在右耳念宣礼词，在左耳念成拜词（إقامة）。然后他轻声念三遍孩子的名字。客人们带来礼物，母亲休养四十天。人人都祈祷这孩子健康、有学问、正直，无论他生在怎样的时代。",
  "tatars:death": "鞑靼人的葬礼遵循伊斯兰教法，没有音乐。遗体被清洗，裹上白色殓布，尽可能在当天下葬，由男人们扛在肩上，一路念诵祈祷。只有男人去墓地。家里，女人们诵读《雅辛章》（يس）；第三天、第七天和第四十天，家人聚在一起祈祷、用餐，追念死者，为他们祈求宽恕。",
  "golden-horde:hunt": "蒙古人的大围猎“涅儿格”（nerge）是一种军事演练。志费尼（جوینی）描述全军如何围成一个方圆需骑行数日的大圈，然后慢慢收紧，把圈内所有野兽赶向中央。没有野兽能逃脱，也没有人能擅自破阵而不受惩罚。最后，可汗先驰入射猎，然后是诸王，再后是士兵。金帐汗国的可汗们在伏尔加河（Идел）草原上保留了这一习俗。",
  "golden-horde:battle": "1241年4月11日，在绍约河（Sajó）畔的莫希（Muhi），拔都汗（Бат хаан）和速不台（Сүбээдэй）迎战匈牙利国王贝拉四世（IV. Béla）的军队。拔都的部下用投石机强攻桥头，速不台则秘密从下游渡河。困在车阵营地里的匈牙利人在逃跑时被砍倒。拔都哀悼在桥头战死的部将巴哈杜尔。几周之内，汗国大军便兵临多瑙河。",
  "golden-horde:gather": "伊本·白图泰（ابن بطوطة）于1334年造访月即别汗（Özbeg）的营地，写道它是一座移动的城市：车上载着毡房，清真寺和市场随之迁移，行进时厨房里炊烟袅袅。在伏尔加河畔的萨莱，来自埃及、热那亚（Genova）、波斯和罗斯的商人云集。营地里，可敦们设宴待客，用金杯银盏奉上马奶酒。",
  "golden-horde:ritual": "1253年被派往蒙古的修士鲁布鲁克的威廉描述了可汗们如何询问未来。把一块羊肩胛骨放进火里，烤到受热开裂。然后把它呈给可汗，由他察看裂纹：若裂纹笔直，计划就会成功；若弯曲，就会失败。在金帐汗国的可汗们皈依伊斯兰教之前，凡是大事都要先这样占卜。",
  "golden-horde:rain": "想象：伏尔加草原上的一个旱年，草短畜瘦。在萨莱，月即别汗（Özbeg）的百姓在聚礼后出城举行求雨拜（استسقاء）。在远处的草原上，放牧人家仍像祖辈那样把奶洒向天空。穆斯林和旧信仰者一同等待着那将决定这个冬天的云。",
  "golden-horde:wind": "想象：一场暴风雪袭击了汗国在伏尔加河（Идел）下游的冬营。风雪刮了三天三夜。毡帐用石头压住，大车围着它们拉成一圈。牧人们轮班让马匹不停走动，免得冻僵。风停后，可汗派骑手到各营清点损失，分发食物。",
  "golden-horde:fire": "1246年，教皇使节柏朗嘉宾（Giovanni da Pian del Carpine）抵达拔都（Бат）的营地时，被告知在觐见可汗之前，他必须连同礼物一起从两堆火之间走过。蒙古人相信火能清除来访者可能携带的毒物或邪祟。火堆旁立着两支长矛，矛间拉着一根绳子，挂满布条。随后他被领进拔都的金帐。",
  "golden-horde:thunder": "柏朗嘉宾（Pian del Carpine）和鲁布鲁克都注意到，在战场上无所畏惧的蒙古人却极其害怕雷电。暴风雨来时，他们把外人赶出帐篷，用黑毡把自己裹起来，躲到风暴过去。若有人遭雷击，他的家人必须从火堆之间走过以求净化，谁也不碰他帐中的东西。",
  "golden-horde:birth": "成吉思汗（Чингис хаан）的长子、拔都（Бат）之父术赤（Зүчи）约生于1182年，就在他的母亲孛儿帖（Бөртэ）从掳走她的蔑儿乞人（Мэргид）手中被救回后不久。有人私下议论说他不是成吉思汗的儿子。成吉思汗接纳了他，但他的弟弟察合台（Цагаадай）有一次当着父亲的面骂他是蔑儿乞的野种。术赤一系后来建立了金帐汗国，成为蒙古诸汗国中延续最久的一个。",
  "golden-horde:death": "柏朗嘉宾（Pian del Carpine）描述过一位蒙古贵族的葬礼。他被安置在帐中，坐在桌前，面前放着一碗肉和一杯马奶，与他一同下葬的有一匹母马和它的马驹，以及一匹备好鞍的马，好让他在另一个世界有奶喝、有马骑。另一匹马被吃掉，马皮塞满填充物，用杆子高高挑在墓上。然后那个地方被隐藏起来。",
  "berbers:hunt": "在如今撒哈拉腹地的阿杰尔高原（ⵜⴰⵙⵉⵍⵉ ⵏ ⴰⵊⵊⴻⵔ）岩壁上，数千年前的画师画下了手持弓箭的猎人，在当时还是绿色稀树草原的大地上追逐长颈鹿和羚羊。图阿雷格牧人至今仍在这些岩画下扎营。想象：黎明时分，一个图阿雷格猎人在霍加尔山（ⴰⵀⴰⴳⴳⴰⵔ）的岩石间追踪一只蛮羊，赤着脚，悄无声息，正如祖父教他的那样；他知道，每一只猎获的动物都必须与人分享。",
  "berbers:battle": "约698年，阿马齐格女王迪赫雅（ⴷⵉⵀⵢⴰ）——阿拉伯人称她为“女先知”卡希娜（الكاهنة）——率领奥雷斯山（ⴰⵡⵔⴰⵙ）的部落迎战倭马亚将领哈桑·伊本·努阿曼（حسان بن النعمان）。她在梅斯基亚纳河畔击溃了他的军队，把他逐出伊夫里基亚（إفريقية）。她善待俘虏，甚至收养了其中一个叫哈立德的人为子。此后五年，奥雷斯山保持了自由。",
  "berbers:gather": "在摩洛哥西南部，阿马齐格妇女捡拾摩洛哥坚果树（ⴰⵔⴳⴰⵏ）的落果，这种树在世界上几乎别处都没有。山羊爬上树枝吃叶子。女人们坐在一起，用两块石头把坚硬的果核一颗一颗敲开，一边聊天唱歌，然后把果仁烘烤、手工研磨，榨出油来。一天的劳作只能得到不到一升。",
  "berbers:ritual": "希罗多德（Ἡρόδοτος）写道，利比亚的纳萨蒙人（Νασαμῶνες）——阿马齐格诸民族的先祖——向亡者求问指引：他们睡在祖先的坟墓上，把梦当作回答。几个世纪后，作为穆斯林的阿马齐格村民通过“求选礼拜”（استخارة）向真主询问，也到当地圣徒的圣墓前祈求，但对长眠于石下的祖先那份古老的敬意依然深厚。",
  "berbers:rain": "干旱的年份，阿马齐格村庄会举行“塔贡贾”（ⵜⴰⵖⵓⵏⵊⴰ）：女孩们把一把大木勺打扮成新娘，抬着它挨家挨户地走，向雨神安扎尔（ⴰⵏⵥⴰⵔ）歌唱。古老的传说讲，安扎尔爱上了一个姑娘，想娶她为新娘；她答应后，雨水便回到了田野。妇女们往玩偶身上浇水，人人都望着阿特拉斯山的峰顶，盼着云来。",
  "berbers:wind": "19世纪的旅行者报告说，1805年，一支从廷巴克图北上前往盐矿的大商队——两千人和几乎同样多的骆驼——遭遇了“毒风”西蒙风（سموم），而水井都已干涸。无一人生还。图阿雷格向导是那片沙漠的主人，他们小心翼翼地察看天空和沙地，因为他们知道风能多么迅速地夺人性命。",
  "berbers:fire": "阿拉伯编年史家讲述，迪赫雅（ⴷⵉⵀⵢⴰ）——卡希娜（الكاهنة）——得知倭马亚大军将卷土重来时，下令族人焚毁从的黎波里（طرابلس）到丹吉尔（طنجة）的城镇、砍倒果园，让入侵者找不到任何值得夺取的东西。橄榄林上空浓烟升腾。她自己的许多族人因此背弃了她。她继续战斗，约703年阵亡于一口后来被称为“卡希娜井”（بئر الكاهنة）的水井旁。",
  "berbers:thunder": "想象：在高阿特拉斯山（ⴰⴷⵔⴰⵔ ⵏ ⴷⵔⵏ），一场夏日风暴降临一座红土房屋的村庄。雷声在悬崖间回荡，妇女们急忙收回屋顶上晾晒的大麦。孩子们数着闪电。清真寺门口的老人说，只要不下冰雹，这场风暴就是一种恩典，他低声为山下的梯田祈祷。",
  "berbers:birth": "想象：在一处图阿雷格营地，一位年轻女子按照头胎的习俗，在母亲的帐篷里分娩。女人们围着她轻声歌唱，接生婆握着她的手。第七天举行命名礼：宰一只公羊，马拉布特（宗教导师）在婴儿耳边低声念出名字，全营以“滕德”（ⵜⴻⵏⴷⴻ）鼓乐和骆驼赛跑来庆祝。没有人知道这孩子将会看见什么。",
  "berbers:death": "在图阿雷格传说中，丁·希南（ⵜⵉⵏ ⵀⵉⵏⴰⵏ）是全体图阿雷格人的女王和始祖母。考古学家在霍加尔山（ⴰⵀⴰⴳⴳⴰⵔ）的阿巴莱萨发现了一座约4世纪的墓葬，一位女子躺在雕花床上，戴着金银手镯。如今阿马齐格人的葬礼遵循伊斯兰习俗：亡者被清洗、裹尸，伴着祈祷当天下葬，没有音乐，只有静默和《古兰经》（القرآن）。",
  "ethiopians:hunt": "想象：17世纪，贡德尔（ጎንደር）附近的高原上，一位埃塞俄比亚贵族带着手下手持长矛骑马出发，追捕一头一直糟蹋庄稼的野牛。猎人们穿过高高的草丛，用短促尖利的喊声互相呼应。野牛冲过来时，一个年轻人寸步不让。当晚全村歌颂他，他的名字将被铭记在夸功歌“富凯拉”（ፉከራ）中。",
  "ethiopians:battle": "1896年3月1日，在阿杜瓦（ዓድዋ），皇帝孟尼利克二世（ምኒልክ）和皇后泰图·贝图尔（ጣይቱ ብጡል）的军队歼灭了入侵的意大利军队。约十万名从各省赶来的埃塞俄比亚人响应了孟尼利克的号召。意大利人损失数千人，在几乎整个非洲都沦为殖民地之际，埃塞俄比亚保持了独立。至今每年人们仍把阿杜瓦作为所有非洲人民的胜利来庆祝。",
  "ethiopians:gather": "埃塞俄比亚人讲述，卡法（ከፋ）有个叫卡尔迪的牧羊人，看见他的山羊吃了一种灌木的红色浆果后跳起舞来。咖啡（ቡና）至今仍野生在那些森林中。在咖啡仪式上，一位妇女在炭火上烘焙生豆，端着冒烟的锅绕场一周让每个人闻香，再用手研磨，分三轮奉上：阿博尔（አቦል）、托纳（ቶና）和巴拉卡（በረካ），最后一轮是祝福。",
  "ethiopians:ritual": "主显节“提姆卡特”（ጥምቀት）前夕，祭司们把各教堂裹着锦缎的圣约柜“塔博特”（ታቦት）抬到水池或溪边。身穿白衣的人群彻夜守候。黎明时分，水被祝圣，洒向每一个人。随后身着刺绣长袍的祭司们摇摆吟唱，摇动“采纳采尔”叉铃（ጸናጽል），合着“凯贝罗”鼓（ከበሮ）缓慢的节拍。这是整个民族的祈祷，为新的一年求福。",
  "ethiopians:rain": "在埃塞俄比亚高原，一切都在等待“基雷姆特”（ክረምት）——6月至9月的大雨季。雨来时，道路变成泥泞，河水上涨，山丘转绿。农民赶着牛犁地，播下苔麸（ጤፍ）。若雨来迟了，祭司们便带领游行，百姓祈祷。1888年至1892年的饥荒年间，雨水断绝；埃塞俄比亚人至今称之为“凶年”（ክፉ ቀን）。",
  "ethiopians:flood": "青尼罗河（ዓባይ）发源于塔纳湖（ጣና ሐይቅ），带来了曾使埃及肥沃的夏季洪水的大部分。埃塞俄比亚的统治者们知道这一点。据说中世纪好几位埃塞俄比亚国王曾威胁开罗的苏丹：若埃及的基督徒受到虐待，他们就让尼罗河改道。无论这是否真能做到，埃及所庆祝的洪水，都始于落在埃塞俄比亚山上的埃塞俄比亚之雨。",
  "ethiopians:wind": "想象：在地球上最炎热的地方之一——达纳基勒洼地，一支由一百头骆驼组成的阿法尔（Qafar）盐队遭遇了沙尘暴。男人们用布蒙住脸，让骆驼围成一圈跪下。从盐滩上手工切下的盐板被捆得紧紧的。几个小时里只有沙和热。然后风停了，他们继续向高原进发。",
  "ethiopians:fire": "9月27日的十字架节“梅斯克尔”（መስቀል），埃塞俄比亚人用树枝搭起高高的金字塔形柴堆“德梅拉”（ደመራ），扎上黄色的梅斯克尔雏菊。它纪念海伦娜皇后的故事：她点起一堆火，循着烟找到了埋藏的真十字架。黄昏时分，人们在歌舞中点燃德梅拉，它倒下时，人们根据倒塌的方向来占卜来年。雨季结束了，花儿开了。",
  "ethiopians:thunder": "想象：一场雨季（ክረምት）风暴降临戈贾姆（ጎጃም）高原。闪电在圆形茅草屋顶上闪烁，雷声沿着青尼罗河（ዓባይ）峡谷滚滚而下。在山顶的一座圆形教堂里，唱诗的学者“德布泰拉”（ደብተራ）在烛光下继续吟唱夜祷，声音低沉而平稳。村里的孩子们隔着墙听着，感到安心，因为吟唱不会因风暴而停止。",
  "ethiopians:birth": "12世纪，扎格维（ዛጔ）王族在罗哈（ሮሓ）生下了一个儿子。传说一群蜜蜂围住婴儿却没有蜇他，母亲认为这是王权的征兆，给他取名拉利贝拉（ላሊበላ），意为“蜜蜂认可他的王权”。他的哥哥忌惮他，试图毒死他。拉利贝拉活了下来，成为国王，下令从整块岩石中凿出十一座教堂，在埃塞俄比亚建起一座新的耶路撒冷（ኢየሩሳሌም）。",
  "ethiopians:death": "埃塞俄比亚人去世后，哭嚎声立即响起；邻居们纷纷赶来。职业哭丧妇“阿尔卡什”（አልቃሽ）即兴唱出称颂死者的挽歌，有时捶打胸口。神父在教堂主持葬礼，遗体葬在教堂墓地。随后是数日的守丧“莱克索”（ለቅሶ），吊唁者在帐篷里陪伴家属。第四十天举行纪念宴“塔兹卡尔”（ተዝካር）。",
  "malians:hunt": "在曼丁人中，猎人属于“栋索通”（donsoton）——一个有自己的秘密、护身符和乐师的兄弟会，乐师们弹奏栋索恩戈尼竖琴（donso ngoni），歌唱伟大猎人的事迹。《松迪亚塔》（ߛߎ߲ߖߊߕߊ）史诗就从他们开始：正是一位猎人兼预言者来到曼丁国王面前，告诉他要娶一个又丑又驼背的女人索戈隆，因为她将为他生下一个强大的儿子。",
  "malians:battle": "约1235年，在基里纳，松迪亚塔·凯塔（Sunjata Keyita）迎战曾征服曼丁的索索（Soso）巫王苏曼古鲁·坎特（Sumaworo Kantɛ）。格里奥（说唱艺人）们说，没有铁器能伤得了苏曼古鲁，直到被嫁给苏曼古鲁为妻的松迪亚塔之妹娜娜·特里班探知了他的秘密：白公鸡的距。松迪亚塔把它装在箭头上射中了他，他的法力就此破灭。马里帝国在那片战场上诞生。",
  "malians:gather": "马里的财富来自尼日尔河（Jɔliba）上游附近的班布克和布雷金矿。旱季里，农民变成矿工，挖掘窄窄的矿坑，妇女们用葫芦瓢淘洗泥土，旋转晃动，直到金粒闪闪发光。马里诸王允许百姓保留金砂，但每一块金块都归国王所有。阿拉伯作家们惊叹不已；曼萨·穆萨（منسا موسى）朝觐时花费了大量黄金，致使开罗（القاهرة）的金价多年低迷。",
  "malians:ritual": "在康加巴，凯塔家族神圣的圆屋“卡马布隆”（Kamabolon）每七年换一次茅草屋顶。村里的男人们爬上去，在一天之内换掉旧草，人群在下面观看。然后来自凯拉、守护口述历史的迪亚巴特（Jabate）家族的格里奥们，在屋内吟诵松迪亚塔（ߛߎ߲ߖߊߕߊ）和马里建国的故事，据说这一仪式可追溯到14世纪。",
  "malians:rain": "想象：在尼亚尼附近的萨赫勒地带，土地已经干了七个月，田地龟裂灰白。五月底，第一阵风带来了雨的气息。人们站在院子外，看着云在南方堆积。第一批大颗雨点落下时，孩子们光着身子笑着冲进雨里，老农们跪下抚摸大地，准备播种小米。",
  "malians:flood": "每年尼日尔河（Jɔliba）都像大海一样漫过它的内陆三角洲。水退时，富拉尼（Fulɓe）牧人在迪亚法拉贝举行盛大的渡河节“德瓦尔”（Dewgal），把牛群赶回河对岸。牧人们和牛群一起游过激流，全镇的人都聚来观看。最膘肥体壮的牛群在歌中受到称颂，把它们带回家的小伙子们备受尊崇。这条河一年两度赐予生命。",
  "malians:wind": "想象：十二月，哈麦丹风从撒哈拉向南吹过廷巴克图（تنبكت）。细尘悬在空中，太阳变成一个苍白的圆盘。在桑科雷清真寺，学者们用皮革包好手稿，合上木箱。学生们捂着嘴继续诵读。三个月里，这风吹干了一切，但寒冷的夜晚晴朗，沙丘上空的星星格外清晰。",
  "malians:fire": "2013年1月，武装团体从廷巴克图（تنبكت）撤退时，纵火焚烧了艾哈迈德·巴巴（أحمد بابا）研究所，烧毁了保存在那里的部分古代手稿。但以阿卜杜勒·卡迪尔·海达拉为首的图书馆员们早已秘密地把数十万份手稿装进米袋和箱子，用驴车和河船偷运出城，送往巴马科（Bamakɔ）。大火夺走了书页；人们保住了几个世纪。",
  "malians:thunder": "想象：雨季伊始，一场风暴降临一个曼丁村庄。雷声滚滚，闪电击中田边一棵高大的猴面包树。人们相信铁匠的手艺能驾驭隐秘的力量，他和长老们一起出去察看那棵树。他们说是风暴选中了它，谁也不会砍它。孩子们悄声说，天空在他们的村子上做了记号。",
  "malians:birth": "格里奥们讲述，索戈隆在一场风暴中生下了松迪亚塔（ߛߎ߲ߖߊߕߊ），国王的另一位妻子萨苏玛嘲笑这个孩子——他直到七岁还不会走路。后来有一天，他的母亲受了萨苏玛的羞辱，松迪亚塔便要来一根铁棒，撑着它把自己拉起来，直到铁棒弯得像一张弓，他站了起来。格里奥们唱道，整个曼丁都随他一同诞生。",
  "malians:death": "曼丁穆斯林迅速安葬亡者，能当天就当天下葬。遗体被清洗，裹上白布，男人们一边念诵祈祷一边把它抬往墓地；葬礼上没有音乐。女人们在家中哀悼。之后几天，亲属们前来问候家属，在许多家庭里，格里奥（ߖߋߟߌ）会追述死者的先祖，好让这个名字和这条血脉不被遗忘。",
  "hausa:hunt": "想象：收获后的旱季，一个豪萨村庄的猎人们聚集在他们的首领——弓之主“萨尔金巴卡”（sarkin baka）——麾下。他们带着弓、矛和护符，领着狗进入灌木丛，排成长长的一列拍打驱赶，把羚羊和珍珠鸡赶出来。夜里他们围着火堆唱猎人之歌，猎获的肉分给每一户人家。",
  "hausa:battle": "据《卡诺编年史》记载，16世纪，扎造的女王阿米娜率领扎里亚的军队征战数十年，征服的土地远至努佩和夸拉拉法，各地统治者向她纳贡。人们记得她在战营和豪萨兰（Ƙasar Hausa）各城周围筑起的土墙，称为“阿米娜之墙”（ganuwar Amina）。人们至今仍对豪萨女孩说：要像巴夸·图伦库的女儿阿米娜那样。",
  "hausa:gather": "按卡诺城自己的说法，卡诺的科法尔马塔（Ƙofar Mata）染坑自1498年起就一直在使用。染工们把布浸进用草木灰和碳酸钾发酵的靛蓝深坑，一次又一次地提起、浸入，直到布几乎变成黑色。然后用木槌捶打，直到布面发亮。穿越撒哈拉的商人们为卡诺的布匹而来，染工的家族至今仍在使用同样的染坑。",
  "hausa:ritual": "开斋节和宰牲节（Babbar Sallah）的会礼之后，卡诺、卡齐纳和扎里亚的埃米尔举行“杜尔巴”（durbar）盛典。身穿绗缝铠甲和鲜艳长袍的骑手们分组冲向埃米尔，在最后一刻勒住缰绳向他致敬，卡卡基长号（kakaki）吹响，鼓声震天。它起初是骑兵检阅；如今是感恩的祈祷和效忠的誓言。",
  "hausa:rain": "想象：五月，卡齐纳的农民每天傍晚都望着天空。土地已经硬了好几个月。南方出现第一场风暴时，伊玛目带领求雨拜，人们施舍。然后云来了，随之而来的是奔向田间的热潮：每一双手，连妇女和孩子也一起，赶在土壤再次干透之前种下小米和高粱。",
  "hausa:flood": "想象：在一个多雨的年份，哈德贾河（Haɗeja）冲破堤岸，漫入湿地。泥砖房屋变软倒塌；各家把能带的东西搬到高处。村长在清真寺安排避难，干燥村庄的邻居们送来粮食。水退之后，土地又变得肥沃，明年的稻子会长得很好。",
  "hausa:wind": "想象：十一月，哈麦丹风来到卡诺，不久尘土就浓得连宣礼塔都看不见了。库尔米市场的商人用草席盖住货物，骆驼跪在城门边，孩子们用母亲的围裹布裹住脸。几个月里，寒冷干燥的风吹裂了嘴唇和皮肤。然后在二月的某一天，风停了，天空忽然变蓝。",
  "hausa:fire": "想象：旱季里哈麦丹风吹拂时，豪萨小镇上一处做饭的火引燃了茅草屋顶。火焰从一户院落跳到另一户。男人们从井边排成长队传递陶罐，妇女们把孩子抱出来，埃米尔的仆从们拆掉屋顶，开出隔火带。到傍晚，整个街区化为灰烬。第二天，邻居们带着粮食、草席和布匹前来。",
  "hausa:thunder": "想象：雨季的第一场大风暴在夜里降临一个豪萨村庄。雷声震动泥墙，闪电把粮仓照得如同白昼。老妇人们说是古老的博里（bori）信仰的精灵在天上跳舞；年轻的伊玛目说那是真主的大能。有一点大家都同意：雨是好的，明天就开始播种。",
  "hausa:birth": "豪萨婴儿出生后，母亲在娘家休养、受人照料，访客们带着礼物前来。第七天举行命名礼“苏纳”（suna）：黎明时宰一只公羊，伊玛目在婴儿耳边低声念出名字，亲友们带着食物和鼓乐挤满院落。人人都祈祷这孩子蒙福、有学问，为家族争光。",
  "hausa:death": "豪萨穆斯林的葬礼简单迅速，没有音乐。遗体被清洗，裹上白布，通常当天就由男人们用灵床抬往墓地，一路念诵祈祷。女人们留在家中。接下来的几天，家属接待吊唁“塔阿齐亚”（ta'aziyya），朋友们陪他们坐着，说：愿真主怜悯亡者，愿他赐你们忍耐。",
  "persians-early:siege": "公元359年，沙普尔二世（شاپور）率军兵临底格里斯河（دجله）上游的阿米达（ܐܡܝܕ）城下。第一天，随波斯军出征的盟国国王格伦巴特斯的幼子被城头射下的一箭夺去了性命。全营为他哀悼了七天，围着遗体歌舞，然后将其火化。哀悼结束后，攻城才开始。七十三天里，士兵们堆起土山、造起塔楼逼近城墙，把悲痛带进了最后的总攻。",
  "persians-early:triumph": "公元588年，将军巴赫拉姆·楚宾（بهرام چوبین）率一支小军，在赫拉特（هرات）附近击溃了来自东方草原的大军。《列王纪》（شاهنامه）讲述战利品如何以长长的驼队西运：黄金、骏马、丝绸帐篷。在泰西封（تیسفون），百姓夹道相迎，城门上鼓声与卡尔奈长号（کرنای）齐鸣，乐师们把这场战役编成歌曲。士兵们作为英雄回到各自的村庄，整整一季，每家酒馆都在唱巴赫拉姆。",
  "persians-early:build": "3世纪，成千上万的工人在舒什塔尔（شوشتر）横跨卡伦河（کارون）筑起了凯撒堤（بند قیصر）——一座长逾五百米、以切割石块砌成的桥堰。石匠们把石块凿方，用铁和铅扣合；另一些人挖渠，把河水引向胡齐斯坦（خوزستان）的田野。工人们唱着歌让锤声整齐划一；约一千四百年间，这座堰坝滋养着磨坊和园圃，直到19世纪才最终被洪水冲毁。",
  "persians:festival": "新年诺鲁孜节（نوروز）始于春分。节前最后一个星期三的夜晚是“火节”（چهارشنبه‌سوری），波斯人跳过篝火，唱道：把你的红给我，拿走我的黄、我的苍白。然后打扫房屋，摆好“七鲜桌”（هفت‌سین），放上七样名字以s开头的东西：麦芽、苹果、大蒜、醋、漆树果粉。一家人连续十三天拜访长辈；第十三天，人人到户外野餐，把麦芽抛入流水。",
  "persians:games": "马球（چوگان）在伊朗历史悠久。《列王纪》（شاهنامه）中，年轻的王子夏沃什（سیاوش）在一位异国国王面前与同伴打球，把球击得高到仿佛触到了月亮，赢得满堂喝彩。几个世纪后，伊斯法罕（اصفهان）大广场（میدان）上的石砌球门柱依然矗立，骑手们曾在宫殿前驰骋，鼓号齐奏。对波斯人而言，这项运动同时考验着马、手与风度。",
  "persians:drought": "1870年至1872年，伊朗全境雨水断绝。麦子枯萎，粮价高得无人买得起，在马什哈德（مشهد）和伊斯法罕（اصفهان）等城市，人们吃草、草根和树皮。旅行者写到空无一人的村庄，以及走向城市的一家家人——可城里同样没有面包。普通人分享所有；面包师被人群围堵；虔诚的施主在圣陵设起粥棚。祖辈们在往后几代人里都轻声谈起那些年。",
  "persians:winter": "想象：大雪封住了阿塞拜疆一个村庄的道路，一连几周。一家人围着“科尔西”（کرسی）过日子——那是一张架在炭火盆上的矮桌，盖着厚厚的被子，大家的腿在下面暖暖的。祖父借着灯光读《列王纪》（شاهنامه）；孩子们敲着核桃，听鲁斯塔姆（رستم）大战白魔（دیو سپید）。外面狼在嚎叫。屋里人们说：冬天很长，但故事更长。",
  "persians-early:plague": "公元628年，卡瓦德二世（قباد）登基几个月后，瘟疫席卷萨珊领土，致命至极，编年史家称之为“希鲁耶瘟疫”（شیرویه）。年轻的国王本人在位不到一年便死于此疫。泰西封（تیسفون）一户户人家陷入死寂；神庙里的火由幸存的人勉力维持。幸存者尽可能地掩埋死者，向阿胡拉·马兹达（اهورامزدا）祈祷，愿谎言失去对世界的掌控。",
  "persians:wedding": "在波斯的婚约礼“阿格德”（عقد）上，新娘新郎坐在婚礼台布（سفره）前，布上摆着镜子、蜡烛、蜂蜜、鸡蛋和甜食。女人们在新人头上撑起一块细布，把两块糖锥相互摩擦，让生活甜美。主婚人三次询问新娘是否同意；宾客们高喊她去采花了、又去取玫瑰水了。最后她说“愿意”，满屋响起欢快的颤音呼喊（کل）。",
  "achaemenids:siege": "约公元前521年，巴比伦（𒆍𒀭𒊏𒆠）起兵反叛大流士（𐎭𐎠𐎼𐎹𐎢𐎺𐎢𐏁），希罗多德（Ἡρόδοτος）说古波斯军队在城下驻扎了十九个月。巴比伦人在城垛上嘲笑他们：等骡子下驹的时候，你们就能攻下这座城了。后来，佐皮鲁斯自己的一头骡子竟真的下了驹。佐皮鲁斯割掉自己的鼻子和耳朵，以逃兵身份投奔城中，赢得信任，然后打开了城门。大流士说，他宁愿要一个完好无损的佐皮鲁斯，也不要二十个巴比伦。",
  "achaemenids:triumph": "想象：长途征战之后，士兵们回到帕尔萨（𐎱𐎠𐎼𐎿）的一个村庄。他们的名字早已写在波斯波利斯的泥板上：每个归来的人分得多少大麦、多少葡萄酒。希罗多德（Ἡρόδοτος）说，古波斯人的理想很简单：在战场上勇敢，多生儿子；国王每年都给儿子最多的人送礼。今晚村里宰一只羊，一位乐师歌唱这次行军，母亲们把儿子数了两遍。",
  "achaemenids:build": "大流士在苏萨（𐏁𐎢𐏁𐎠）的建城铭文列出了修建他宫殿的人：巴比伦人烧砖，雪松来自黎巴嫩，黄金来自萨迪斯和巴克特里亚，青金石和红玉髓来自粟特。爱奥尼亚和萨迪斯的石匠打磨石料，米底人（𐎶𐎠𐎭）和埃及人加工黄金和浮雕。波斯波利斯（𐎱𐎠𐎼𐎿）泥板显示，工人们的报酬是大麦、葡萄酒和羊，妇女生产后还能领到额外的口粮。大流士写道：凡所下令者，皆已完成。",
  "achaemenids:voyage": "希罗多德（Ἡρόδοτος）说，大流士（𐎭𐎠𐎼𐎹𐎢𐎺𐎢𐏁）想知道印度河在哪里入海。约公元前515年，他派卡里扬达的斯基拉克斯（Σκύλαξ ὁ Καρυανδεύς）等人乘船顺流而下。他们向东航行，进入大洋，再沿阿拉伯海岸西行；第三十个月时，他们抵达埃及附近的红海。对古波斯的书吏来说，这是一张以月份绘成的地图；对水手们来说，这是一场终于结束的漫长乡愁。",
  "achaemenids:festival": "在秋季的密特拉节“密特拉卡纳”（Mithrakana）——祭祀契约与晨光之神密特拉——古波斯宫廷互赠礼物、大摆筵席。阿忒纳乌斯（Ἀθήναιος）引用萨摩斯的杜里斯（Δοῦρις ὁ Σάμιος）的话写道，这是一年中唯一一天，大王可以喝醉，并当众跳波斯舞。想象波斯波利斯（𐎱𐎠𐎼𐎿）的大厅：号角与竖琴齐鸣，国王走进贵族之中，笑声升到雪松木的屋顶。",
  "achaemenids:games": "希罗多德（Ἡρόδοτος）说，古波斯男孩从五岁到二十岁只学三件事：骑马、射箭、说真话。色诺芬（Ξενοφῶν）描述过他们的比赛：赛马、驰马掷标枪、在长辈注视下一同狩猎，长辈们会表扬最优秀的人。一个在疾驰中射中目标的男孩，会听见自己的名字被高声呼出，他的家人会记住那一天。",
  "achaemenids:drought": "伊朗高原干旱，古波斯农民靠地下引来的水为生。波利比乌斯（Πολύβιος）写道，波斯国王规定：谁第一个通过坎儿井（قنات）——从山脚下挖出的绵延数公里的地下水道——把水引到某块土地上，谁就可以使用这块地五代人之久。旱年里，各家不停地盯着坎儿井出口的细流。只要它还在流，村子就活着；它一变小，所有人都沉默了。",
  "achaemenids:quake": "希罗多德（Ἡρόδοτος）写道，公元前490年，达提斯率领的古波斯舰队驶过圣岛提洛（Δῆλος）时，这座岛发生了记忆中唯一的一次地震。达提斯曾出于敬意放过了它，还在祭坛上焚香。水手们从甲板上回望，看见神庙在海中颤抖。希腊人认为这是灾祸将至的征兆；水手们只是划得更快了。",
  "achaemenids:winter": "在埃斯库罗斯（Αἰσχύλος）的剧作《波斯人》（Πέρσαι）中，一位信使讲述公元前480年古波斯军队从希腊撤退的情形。冬天来得早；一夜之间斯特律蒙河（Στρυμών）封冻，从未向大地诸神祈祷过的人也跪下谢恩，然后开始踏冰过河。太阳升起、冰面变暖时，冰在他们脚下崩裂。信使说，最早淹死的人，倒是幸运的。",
  "achaemenids:plague": "希罗多德（Ἡρόδοτος）讲述，公元前480年从希腊回国的漫长行军中，古波斯军队断了粮。士兵们吃草，剥食树皮和树叶；随后瘟疫和痢疾在军中爆发。病人被留在色萨利（Θεσσαλία）和马其顿的城镇里，听凭照料或死去。那些抵达萨迪斯的人没带回多少歌，却在火炉边留下了许多空位。",
  "achaemenids:wedding": "公元前324年，在苏萨（𐏁𐎢𐏁𐎠），九十对新人按古波斯的方式在同一天成婚。椅子排成长长的一列；新郎们坐下，举杯祝酒，然后新娘们进来，各自坐到丈夫身边，丈夫握住她的手亲吻她。阿里安（Ἀρριανός）说，新郎们随后把新娘领回家。在镀金立柱撑起的大帐下，乐师们演奏了整整五天的宴乐。",
  "saracens:siege": "想象：袭掠者切断了一个贝都因氏族通往平原的路，各家把骆驼赶进山中一处岩石避难所。骆驼围成一圈跪下，妇女和孩子在圈内；男人们手持长矛和老式火绳枪守住狭窄的通道。水按杯计量分配，奶干了，孩子们也不再哭着要奶喝。第三夜，诗人轻声吟诵起祖辈们当年在此坚守的诗句。",
  "saracens:triumph": "想象：黄昏时分，骑手们赶着袭掠得来的骆驼穿过砾石平原归来，营地远远就看见了他们扬起的尘土，然后才看清他们的脸。妇女们跑出来发出高亢的颤音欢呼（زغرودة）；孩子们爬上帐篷绳张望。那天晚上，咖啡壶在人们手中传递，煮了一只羊，部落诗人站起来吟诵。一件功业只有活在一首“盖绥达”长诗（قصيدة）里，才算真正成立。",
  "saracens:build": "贝都因人的家是“毛发之屋”（بيت الشعر）。妇女们纺黑山羊毛，在沙地上用木桩固定的地织机上织成长长的窄条，再把布条缝在一起。营地迁移时，大家一起搭帐篷：立起柱子，拉紧绳索钉好，挂起织成的帘子，把男人区和女人区隔开。下雨时，毛发膨胀，屋顶便自己密封起来。",
  "saracens:voyage": "11世纪，希拉勒部落（بنو هلال）带着牲畜和家眷离开上埃及，向西横穿北非。讲述他们迁徙的史诗《希拉勒人西迁记》（تغريبة بني هلال），至今仍有埃及诗人伴着拉巴巴琴（ربابة）夜复一夜地吟唱：乔装在前方探路的阿布·扎伊德（أبو زيد），美丽的贾齐娅（الجازية），为寻找绿地而进行的漫长流浪。对贝都因人而言，这次迁徙成了一首永不终结的歌。",
  "saracens:festival": "伊斯兰以前，阿拉伯人每年在禁止征战的圣月里，聚集在塔伊夫（الطائف）附近的欧卡兹集市（عكاظ）。各部落搭起帐篷，交易皮革、香料和骆驼，最重要的是聆听诗人吟诗。传说最好的颂诗被尊为《悬诗》（المعلقات）。在欧卡兹起身吟诗、令全场倾倒的贝都因诗人，能为整个部落赢得一代人的荣耀。",
  "saracens:games": "贝都因说书人记得6世纪达希斯（داحس）与加布拉（الغبراء）的那场赛马：两匹名马，一匹属于阿布斯部落（عبس），一匹属于祖卜彦部落（ذبيان），以一群骆驼为赌注，在漫长的沙漠赛道上比试。一方的人埋伏在山谷里，惊吓了领先的马。关于谁真正获胜的争执演变成了一场长达四十年的战争。后来老人们说：永远别拿你的部落去赌一匹马。",
  "saracens:drought": "想象：冬雨已经两次没来，部落牧地（ديرة）的水井只能打上泥浆。骆驼的驼峰塌了下去；山羊在饿死之前被一只只宰掉。长老们骑马跑了好几天，去请求一个远方部落允许他们在其井边饮水，以最古老的亲缘之谊相托。夜里，一位老人吟诵起远方闪烁的闪电——闪在别人的土地上。",
  "saracens:quake": "1256年，麦地那（المدينة）附近的大地震动了好几天，随后拉哈特熔岩原（حرة رهط）的黑色熔岩地裂开了。编年史家写道，火光把夜晚照得通明，麦地那的人们可以借光读书，远在沙漠另一头也能看见那片光芒。一条熔岩之河缓缓向北朝城镇爬去，在城外停住了。贝都因牧人在山上观望，既祈祷又恐惧。",
  "saracens:plague": "公元639年，耶路撒冷（القدس）附近的阿姆瓦斯（عمواس）爆发瘟疫，染病的是阿拉伯士兵及其家眷，其中许多人来自沙漠部落。数以万计的人死去，包括统帅阿布·欧拜达（أبو عبيدة）。传述说，哈里发没有进入疫区而是折返时，有人问：你是在逃避真主的前定吗？他回答：我们从真主的前定逃向真主的前定。幸存者带着消息回到了帐篷。",
  "saracens:wedding": "想象：在一场贝都因婚礼上，新娘坐在骆驼背上摇晃的帘轿（هودج）里，前往她的新帐篷，女眷们在旁歌唱。男人们站成长长的一排，吟唱拍手的“萨赫加”（سحجة），应和着即兴吟诵新郎诗句的诗人。枪声朝天鸣响，羊肉配米饭和酸奶煮好了，新人的帐篷稍稍远离营地而立。",
  "abbasids:siege": "812年和813年，在两兄弟之间的战争中，巴格达（بغداد）遭到围困。投石机轰击圆城，整片街区燃烧，市场里被称为“赤身者”（'urat）的穷人们，头顶装着石头的筐子、手持芦苇盾牌在街头作战。粮食吃光了；一家家人逃过底格里斯河（دجلة）。诗人胡莱米写下长篇哀歌：巴格达，曾是人间的天堂，如今它的人民在哭泣。",
  "abbasids:triumph": "想象：夏季征战之后，边境部队回到巴格达（بغداد）。人群从呼罗珊门一路夹道相迎；男孩们爬上城墙，妇女们在屋顶上观看，布克号（buq）与纳卡拉鼓（naqqara）彼此应和。晚上市场开到很晚，灯火通明，庭院里弹乌德琴（عود）的歌手们演唱关于这次征战的新诗。看到儿子骑马经过的母亲们当场施舍。",
  "abbasids:build": "848年至852年间，哈里发穆塔瓦基勒建造了萨迈拉（سامراء）大清真寺，它一度是世界上最大的清真寺。成千上万的阿拉伯及其他民族的工人烧砖、砌墙，建起了它的宣礼塔“螺旋塔”（الملوية）——一座高五十米的螺旋形塔，外侧有坡道盘旋而上。砖匠们一边码窑一边唱歌。那座宣礼塔至今仍矗立在底格里斯河平原上。",
  "abbasids:voyage": "921年，艾哈迈德·伊本·法德兰（أحمد بن فضلان）随使团从巴格达（بغداد）出发，出使伏尔加保加尔人。他穿过伊朗和花剌子模（خوارزم），然后是冰封的草原，他写道，那里冷得他的胡子冻成了一块冰，人的手会粘在铁器上。商队走了将近一年。当他们终于看见那条大河和保加尔国王的帐篷时，伊本·法德兰把一切都记了下来，满怀好奇与惊叹。",
  "abbasids:festival": "想象：阿拔斯时代巴格达（بغداد）斋月（رمضان）的最后一个傍晚，人们爬上屋顶寻找细细的新月。一旦看见，呼喊声便从一个屋顶传到另一个屋顶，街上鼓声响起。第二天早上，人人穿上新衣，去参加开斋节（عيد）会礼，然后探亲访友。孩子们揣着糖果和硬币；厨子们卖椰枣糕和卡塔伊夫（قطايف）；整座城市飘着玫瑰水的香气。",
  "abbasids:games": "阿布·伯克尔·苏利（أبو بكر الصولي）是10世纪初巴格达（بغداد）最伟大的象棋手。他在宫中与哈里发穆克台菲（المكتفي）的冠军棋手马瓦尔迪（الماوردي）对弈，把对方杀得片甲不留，偏爱后者的哈里发说：你的玫瑰水变成尿了。苏利能下盲棋，写过象棋残局的书，他的名字成了一句俗语：下得像苏利一样。",
  "abbasids:drought": "想象：冬雨落空，幼发拉底河（الفرات）的运河水位很低。在伊拉克的一个小城里，伊玛目召集人们举行求雨拜（صلاة الاستسقاء）。他们黎明时穿着旧衣走出城门，谦卑恭顺，带着孩子，甚至带着牲畜。礼拜之后，伊玛目把斗篷翻过来穿，象征真主将扭转旱情。然后所有人都望向天空，寻找云的踪迹。",
  "abbasids:quake": "977年和978年，一连串地震震撼了海湾上阿拉伯与波斯的大港尸罗夫（سيراف），持续七天。尸罗夫的商人曾派船前往印度和中国；城中房屋用柚木建造，高达数层。许多房屋倒塌，人们逃往海边。商人们把生意迁到了基什岛（كيش），这座古老的港口渐渐被遗忘。",
  "abbasids:winter": "想象：一个罕见的寒冷年份，雪落在巴格达（بغداد），白白地覆在椰枣树上。从没见过雪的孩子们用手捧起雪互相投掷。市场上木炭价格翻了一番；穷人把自己所有的斗篷都裹在身上，清真寺里挤满了在灯旁过夜的人。诗人们写诗，描述这位来自北方的奇异白色访客。",
  "abbasids:plague": "1348年，黑死病传到了开罗（القاهرة）。史家麦格利齐（المقريزي）写道，有些日子一天就死去数千人，棺材不够用，死者被放在木板和门板上抬走，整条整条的街道陷入寂静。宣礼声和葬礼上的《古兰经》（القرآن）诵读声从未间断。工匠、学者、奴隶和埃米尔同样死去。事后，阿拉伯学者们为幸存者写下了慰藉之书。",
  "abbasids:wedding": "825年，哈里发马蒙（المأمون）在法姆锡勒赫（فم الصلح）迎娶了维齐尔之女布兰（بوران）。编年史家说，她的祖母从金盘中把一千颗大珍珠倾洒在新人身上，一支重两百磅的龙涎香蜡烛照亮了房间。外面，麝香球被抛向人群。普通阿拉伯人的婚礼规模小得多，却有着同样的精神：香气、音乐与慷慨，一直持续到天明。",
  "ayyubids:siege": "1189年至1191年漫长的阿卡（عكا）围城期间，一个名叫伊萨（عيسى）的黎凡特泳者夜里为守军传送书信和钱财，腰缠金带，从敌船底下游过。巴哈丁（بهاء الدين）写道，有一夜他没有到达。几天后，他的遗体被冲上海滩，金子仍系在身上。阿卡人说，他至死都守住了所托之物。",
  "ayyubids:triumph": "想象：长途征战之后，士兵们经由天堂门（باب الفراديس）骑马回到大马士革（دمشق）。城堡上的军乐队（طبلخانة）奏响，大库斯鼓（كوس）隆隆作响，纳菲尔号（نفير）声声应和。妇女们从格子窗里抛下玫瑰花瓣和糖衣杏仁；店主们把地毯挂在摊位上。咖啡馆和甜品店里，说书人（حكواتي）已经把归来的人编进了安塔拉（عنترة）的古老故事。",
  "ayyubids:build": "约1209年，在扎希尔·加齐（الظاهر غازي）治下，黎凡特石匠在阿勒颇（حلب）的巨大土丘上重建了城堡。他们给山坡铺上光滑的石砌斜坡，挖出深深的护城河，建起桥梁和带折角入口的高大城门。城内挖了蓄水池，建了清真寺和宫殿。石匠们把每块石头拖上山时都在唱歌；他们的标记至今仍可在墙上找到。",
  "ayyubids:voyage": "每年，朝觐（حج）商队从大马士革（دمشق）出发前往麦加（مكة），要穿越沙漠走一个多月。全城人都出来送行：队首是骆驼背上装饰华丽的驼轿“马哈米勒”（محمل），鼓笛齐奏，朝圣者身着盛装。各家在城门口哭泣拥抱；谁也不知道谁能回来。几周后商队归来时，同样的人群唱着歌把他们迎回家。",
  "ayyubids:festival": "伊本·赫里康（ابن خلكان）描述了13世纪初埃米尔古克布里（كوكبوري）治下伊尔比勒（أربيل）的圣纪节（المولد），即先知诞辰。路边排列着数层高的木头亭台，每座都挤满了歌手、乐师和皮影艺人，人们从巴格达（بغداد）和摩苏尔（الموصل）赶来观看。火把彻夜燃烧，宰了羊和骆驼款待人群，苏非们一直唱到天明。黎凡特各城则以蜡烛和甜食来庆祝。",
  "ayyubids:games": "阿尤布王子们热爱马球，大马士革（دمشق）在巴拉达河（بردى）畔有一片绿色的广场，骑手们在那里打球。巴哈丁（بهاء الدين）写道，萨拉丁（صلاح الدين）即使在征途中也打马球。想象场边的人群：弯曲的球杆，皮制的球，马匹在尘土中回旋，每进一球军乐队便擂鼓。黎凡特的男孩们在小巷里徒步玩同样的游戏，用一根棍子和一个布球。",
  "ayyubids:drought": "1200年，尼罗河（النيل）没有上涨。住在开罗（القاهرة）的医生阿卜杜勒·拉蒂夫·巴格达迪（عبد اللطيف البغدادي）记下了随后的岁月：粮食从市场上消失，村庄人去屋空，穷人能找到什么就吃什么，死者横卧街头。他把所见记录下来，好让无人忘记。饥民的队伍逃往叙利亚，黎凡特的城镇向他们敞开了城门。",
  "ayyubids:quake": "1202年5月20日黎明前，一场大地震袭击了黎凡特。纳布卢斯（نابلس）几乎被夷为平地；阿卡（عكا）和提尔（صور）的城墙倒塌；大马士革（دمشق）大清真寺部分坍塌。阿卜杜勒·拉蒂夫·巴格达迪（عبد اللطيف البغدادي）写道，从埃及到亚美尼亚都能感觉到震动。一家家人在露天睡了好几周，不敢回到屋顶下。然后，他们慢慢清理石块，开始重建。",
  "ayyubids:winter": "想象：大雪封住了黎巴嫩山（جبل لبنان）的山口。在一个石头村庄里，一家人围着馕坑（تنور）烤薄饼，喝着香料茶，听着狂风呼啸。长者们储存着秋天的小麦、葡萄干和无花果干；只要大家分享，就够吃。晚上，一位邻居弹起乌德琴（عود），唱起古老的“马瓦勒”（موال）。他们告诉孩子们：春天总会沿着山谷回来。",
  "ayyubids:plague": "1348年7月，黑死病在大马士革（دمشق）每天夺去两千人的性命，伊本·白图泰（ابن بطوطة）当时就在城中。他写道，人们斋戒三天，然后一起走向足迹清真寺（مسجد الأقدام）：埃米尔、圣裔、法官，捧着《托拉》（תּוֹרָה）的犹太人，捧着福音书的基督徒，妇女和孩子，人人赤足，一边祈祷一边哭泣。他认为此后真主为他们减轻了瘟疫。",
  "ayyubids:wedding": "黎凡特的婚礼要持续好几天。在指甲花之夜，新娘的女友们为她的双手绘上花纹，为她歌唱。第二天是迎亲游行“扎法”（زفة）：鼓手和歌手领着新郎走过街道，每个阳台上都响起女人们的颤音欢呼。宴席上，男人们挽起手臂跳“达布卡”舞（دبكة），合着双管笛“米吉威兹”（مجوز）的旋律踏出节奏，新娘的嫁妆则被抬往新家，让所有人观看。",
  "turks:siege": "1097年5月，一支来自西方的大军包围了尼西亚（Νίκαια），乌古斯苏丹基利吉·阿尔斯兰（قلج ارسلان）把家眷和财宝留在了这里。七周里，突厥守军坚守湖边的城墙，攻城塔步步逼近，阵亡战友的头颅被抛过城墙。当身后的湖面上出现船只时，守军知道自己已被切断。他们悄悄献城投降，保全了城中的妇女和孩子。",
  "turks:triumph": "在《先祖科尔库特书》（Kitab-ı Dedem Korkut）中，每当英雄苦战归来，乌古斯人就在绿色草地上搭起白色大帐，宰杀种马、公羊和骆驼，宴饮四十天四十夜。然后白胡子歌者科尔库特老人带着他的科布兹琴（kopuz）到来，弹奏着把英雄的故事编成歌：让它被传颂吧，他说，让它口口相传。每个故事都以他的祝福结束。",
  "turks:build": "乌古斯人家需要为毡房做新毛毡时，营地的女人们会聚在一起共同制作。她们把羊毛铺在芦苇席上，洒上热水，卷紧，然后用脚和手臂把卷子来回滚压好几个小时，唱着劳动号子保持节奏。到傍晚，毛毡变得结实厚密，可以在冬天盖在毡房上了。之后全营一起吃饭。",
  "turks:voyage": "《乌古斯可汗传》（Oğuz Nâme）讲述乌古斯可汗（Oğuz Kağan）如何率领族人走出东方。一天早晨，一道光照进他的帐篷，从光中走出一匹巨大的苍狼，说：我将走在你的大军前面。苍狼带领着畜群、大车和家家户户渡过河流、翻越山岭，它停在哪里，人们就在哪里扎营。历史学家说，乌古斯人于10世纪从咸海附近的草原西迁；而歌谣记住的是那匹狼。",
  "turks:festival": "春天的诺鲁孜节（Nevruz），乌古斯人及其后裔纪念额尔古涅昆（Ergenekon）传说：他们的祖先世世代代被困在一个铁山环绕的山谷中，后来一位铁匠用七十个风箱熔化了铁崖，一匹苍狼领着他们走进了开阔的世界。所以在新年这一天，各家跳过篝火，铁匠在铁砧上敲打烧红的铁，纪念大山敞开的那一天。",
  "turks:games": "在《先祖科尔库特书》（Kitab-ı Dedem Korkut）中，巴姆西·贝伊雷克（Bamsı Beyrek）去见与他有婚约的姑娘巴努·奇切克（Banu Çiçek），她向他挑战：先赛马，再射箭，然后摔跤。贝伊雷克赢了赛马和射箭，摔跤时也只是勉强把她压住。于是她笑了，接受了他。乌古斯的少男少女们在每次聚会上都玩同样的游戏：赛马、射箭、在草地上摔跤。",
  "turks:drought": "想象：春雨没有来，到六月，高原上的乌古斯牧场已一片枯黄。泉水一眼接一眼地干涸。全营的男女老少一起登上一座山丘，带着献祭的羊。他们祈雨，然后把肉煮熟分给每个人，连最穷的人家也有份。老婆婆说，只要人们肯分享，天空就会记得他们。",
  "turks:quake": "想象：在多次发生地震的埃尔津詹，一个乌古斯牧人夜里被狗的嚎叫惊醒。随即大地轰鸣；泥砖房屋像帐篷一样折倒。到早上，一家家人坐在田野里，包扎伤口，清点谁不见了。邻居们送来面包和毛毡毯子。老人们说，大地驮在一头巨牛的角上，是它在挪动身子。",
  "turks:winter": "想象：乌古斯营地已迁到一处避风山谷中的冬营地（kışlak）。雪堆在毛毡毡房外；屋里，牛粪火闷燃着，一家人和新生的羊羔一起盖着羊皮睡觉。男人们骑马出去凿开溪面的冰，好让马饮水。夜里，一位歌者弹起科布兹琴，讲述萨鲁尔·卡赞的故事，人人都在等待第一茬青草。",
  "turks:plague": "想象：消息传到一个乌古斯营地：商路沿线的城镇里有了疫病。长老们当即决定：收起毡房，把畜群赶上高山牧场，不见任何人。几周里，各家分开居住，只派一名骑手到邻营的边上，隔着距离喊话传递消息。孩子病了，母亲整夜守着他，唱着她母亲曾唱过的歌。",
  "turks:wedding": "在乌古斯人中，婚礼是一场持续多日的盛宴。在《先祖科尔库特书》（Kitab-ı Dedem Korkut）中，巴姆西·贝伊雷克（Bamsı Beyrek）终于迎娶巴努·奇切克（Banu Çiçek）时，人们搭起新房帐篷，宰杀马和羊，射手们射靶，骑手们赛马。贝伊雷克射出一箭，箭落在哪里，新房帐篷就立在哪里。女人们为新娘歌唱，科布兹琴彻夜弹奏，科尔库特老人为新人唱起祝福。",
  "ottomans:siege": "1877年夏秋，奥斯曼帕夏（Osman Paşa）麾下的士兵面对规模大得多的军队，坚守普列文（Plevne）城达五个月之久。他们挖掘壕沟和堡垒，击退了三次大规模进攻，然后随着冬天来临慢慢陷入饥饿。12月，粮食耗尽，他们试图突围，没能成功。安纳托利亚突厥人至今仍唱着民歌《普列文进行曲》（Plevne Marşı），哀悼那些坚守在那里、再也没有回家的年轻人。",
  "ottomans:triumph": "喜讯传到伊斯坦布尔（استانبول）时，全城举行“多纳马”（donanma）灯节：三天三夜，每座房屋、店铺和清真寺都挂出油灯。金角湾（Haliç）里的船只挂满灯笼，烟火在水面上空升起，军乐队（مهتر）在广场上奏响苏尔奈和大鼓（kös）。皮影戏艺人、杂技演员和说书人在人群中表演。安纳托利亚突厥人会走上一整夜，只为看看这些灯火。",
  "ottomans:build": "1550年至1557年，建筑师锡南（سنان）在伊斯坦布尔（استانبول）的第三座山丘上建造了苏莱曼尼耶清真寺。它的账簿保存至今：数千名工人，约一半是基督徒、一半是穆斯林，有来自巴尔干的石匠、木匠、玻璃匠、雕刻匠，每人按日计酬。据说锡南等了好几年，让地基沉降稳定后才砌起穹顶。安纳托利亚突厥人至今仍说，他的清真寺仿佛漂浮在城市上空。",
  "ottomans:voyage": "艾弗利亚·切莱比写道，1630年他梦见自己身处一座满是先知圣门弟子的清真寺。他本想祈求“说情”（şefaat），却结结巴巴说成了“旅行”（seyahat）。先知微笑着把两样都赐给了他。此后艾弗利亚用了四十年游历四方，从维也纳（Wien）到埃及，从高加索到阿拉伯，在十卷本的《游记》（سیاحتنامه）中记录下歌谣、食物和方言，对所见的一切都兴致盎然。",
  "ottomans:festival": "5月5日至6日之夜的希德雷莱孜节（Hıdırellez），标志着先知希德尔与伊利亚斯在人间相会、夏天开始的日子。安纳托利亚突厥人把写在纸上的心愿或一条丝带系在玫瑰丛上，在花下埋些小信物。年轻人跳过篝火，姑娘们把戒指投入一罐水中，用称为“马尼”（mani）的诗句占卜，一家家人在泉边和绿草地上野餐。",
  "ottomans:games": "至少从14世纪起，每年夏天油摔跤手们都会聚集在埃迪尔内（ادرنه）附近的克尔克普纳尔（Kırkpınar）。传说四十名士兵曾在那里两两摔跤，其中两人一直摔到双双死去；他们倒下的地方涌出了一眼泉水。摔跤手们穿着皮裤，全身抹上橄榄油，开赛前先祈祷。达乌尔鼓（davul）和苏尔奈管奏响，司仪（cazgır）为每对选手高声吟诵诗句。",
  "ottomans:drought": "1873年至1875年，安纳托利亚中部雨水断绝，安卡拉、科尼亚和开塞利的收成全面崩溃。牛羊死亡，一家家人走向城镇，村庄人去屋空，数以万计的人死于饥饿。人们在田野里求雨，由伊玛目带领做求雨祷告（yağmur duası）；仍有余粮的邻居拿出来分享。他们的孙辈把这些年记作“大饥荒之年”。",
  "ottomans:quake": "1509年9月10日，一场地震猛烈袭击伊斯坦布尔（استانبول），人们称之为“小末日”（قیامت صغری）。一千多座房屋和一百多座清真寺倒塌，海浪越过城墙，余震持续了好几周。一家家人在花园和空旷的广场上露宿，不敢在屋顶下睡觉。随后，成千上万的工人从安纳托利亚被召来重建城市。",
  "ottomans:winter": "1621年冬，博斯普鲁斯海峡（Boğaziçi）从此岸到彼岸全部封冻。编年史家写道，人们踏冰从于斯屈达尔走到伊斯坦布尔（استانبول），金角湾里的船只被牢牢冻住。粮食无法经海路运来，面包短缺，穷人能找到什么木头就烧什么。安纳托利亚突厥人把它记作“连大海都静止了的冬天”。",
  "ottomans:plague": "佛兰德使节奥吉耶·吉斯兰·德·布斯贝克在16世纪五六十年代住在伊斯坦布尔（استانبول），一次又一次地目睹瘟疫来袭。他写道，安纳托利亚突厥人并不逃避瘟疫，他们相信每个人的死期都由真主写在额头上。他们清洗死者，为其举行殡礼，迅速下葬，然后照常生活。当瘟疫进入他自己的家中时，布斯贝克也发现除了等待别无他法。",
  "ottomans:wedding": "安纳托利亚突厥人的婚礼始于“指甲花之夜”（kına gecesi）：新娘蒙着红色面纱坐着，女人们唱着离开娘家的哀伤歌曲，把指甲花按进她的掌心。第二天，达乌尔鼓和苏尔奈管领着新郎家的人去迎亲，队伍最前面举着一面旗。仪式之后，新郎走进新房时，朋友们捶着他的背，祝他好运。",
  "armenians:siege": "1064年，塞尔柱大军包围了阿胡良河（Ախուրյան）上方悬崖上的阿尼城（Անի）——“一千零一座教堂之城”。二十五天里，城墙上的亚美尼亚人在投石机的轰击和日渐短缺的粮食中坚守。城墙被攻破后，许多人死在街道和教堂里。编年史家阿里斯塔克斯·拉斯季韦尔茨（Արիստակես Լաստիվերտցի）为阿尼写下哀歌：它节日的歌声何在，它歌者的嗓音何在？如今只听得见哭泣。",
  "armenians:triumph": "在亚美尼亚史诗《萨松的大卫》（Սասունցի Դավիթ）中，年轻的大卫骑着烈马贾拉利（Քուռկիկ Ջալալի），手持父亲的闪电之剑出征，击败了曾向萨松勒索贡赋的巨人姆斯拉·梅利克（Մսրա Մելիք）。他骑马回家时，山里的人们带着面包和葡萄酒下山迎接，老人们流下眼泪，女人们放声歌唱。歌者们在村庄里传唱这个故事一千年，每个听众都觉得自己是萨松的一员。",
  "armenians:build": "13至14世纪，大师莫米克（Մոմիկ）在诺拉万克修道院（Նորավանք）雕凿石头：圣母教堂，以及精细得如同蕾丝的十字石（խաչքարեր）。亚美尼亚石匠切割柔软的红色凝灰岩，用手塑造每一块石头，不用铁件就把它们拼合在一起。村民们把石头拖上峡谷。在完工的墙上，建造者们有时刻下自己的名字，请在那里祈祷的人记住他们。",
  "armenians:voyage": "1682年至1693年间，新朱勒法（Նոր Ջուղա）的亚美尼亚商人霍夫汉内斯·朱加耶齐（Հովհաննես Ջուղայեցի）从伊斯法罕（Սպահան）出发前往印度，又翻越喜马拉雅山到达拉萨（ལྷ་ས），为合伙人运送丝绸、布匹和白银。他用亚美尼亚文记账，记下每一个价格和每一条道路。家乡的亚美尼亚家庭要等好几年才收到来信；商队归来时，整个街区的人都出来听故事。",
  "armenians:festival": "在古代亚美尼亚，新年“纳瓦萨尔德”（Նավասարդ）在收获之后的八月到来。摩西·霍列纳齐讲述，人们聚集在巴加万（Բագավան），国王在那里向众神献祭，有竞技、歌唱、舞蹈和骑手比赛。朝圣者带来水果和鲜花，节庆持续多日。即使在皈依基督教之后，纳瓦萨尔德这个名字仍作为亚美尼亚历的第一个月流传下来。",
  "armenians:games": "在亚美尼亚的乡村节日上，年轻人在观众环绕的草地上进行传统摔跤“科赫”（կոխ）。达霍尔鼓（դհոլ）手和苏尔奈管（զուռնա）手为每一场比赛奏起快曲，摔跤手们抓着腰带和肩膀绕圈周旋，老人们大声出主意。获胜者被高高举起，得到一只公羊或一块蛋糕。然后音乐转为舞曲，人人都加入圆圈。",
  "armenians:drought": "干旱的年份，亚美尼亚的乡村孩子们做一个叫“努林”（Նուրին）的玩偶，给它穿上鲜艳的布衣，抬着它挨家挨户地唱：努林，努林，到我们这儿来，带来雨，带来面包。每到一户门前，女人们就往玩偶和孩子们身上浇水，给他们鸡蛋、黄油或面粉。孩子们浑身湿透地笑着；母亲们抬头望着万里无云的天空，盼着这首歌能被听见。",
  "armenians:quake": "1679年6月4日，一场大地震袭击了阿拉拉特（Արարատ）河谷。埃里温（Երևան）附近的村庄倒塌，加尔尼（Գառնի）悬崖上那座屹立了约十六个世纪的古老列柱神庙轰然倒成一堆石头。亚美尼亚家庭埋葬了死者，重建了教堂。神庙的石块在原地躺了将近三百年，才被一块一块地重新竖起。",
  "armenians:winter": "想象：厚厚的积雪覆盖着高原上的一个亚美尼亚村庄，一家人围着“托尼尔”（թոնիր）——嵌在地面里的陶土烤炉——过日子。炉上架着一张盖着厚被的矮桌，人人把脚伸到下面取暖。早上祖母在托尼尔的内壁上烤拉瓦什薄饼；夜里祖父讲《萨松的大卫》（Սասունցի Դավիթ）的故事。外面风在吹，隔壁的牛让屋子暖和起来。",
  "armenians:plague": "想象：瘟疫来到了亚美尼亚高原上的一个村庄。每死一个人，神父就敲一次教堂的钟，直到人们恳求他别再敲了。门上做了记号，各家把面包放在门槛上，留给屋里的病人。傍晚，女人们聚在教堂里，一起轻声唱起“沙拉坎”（շարական）圣歌。孩子们被送到夏季高山牧场，跟着祖父母离开村子，在那里等待。",
  "armenians:wedding": "亚美尼亚婚礼上，新郎的母亲在新家门口迎接新人。她在两人肩上各搭一张薄薄的拉瓦什饼（լավաշ），愿他们永不挨饿，两人各自在脚下踩碎一个盘子求个好运。教父“卡沃尔”（քավոր）主持仪式。然后达霍尔鼓（դհոլ）和苏尔奈管响起，人人围成圆圈跳“科恰里”舞（քոչարի），宴席一直持续到天明。",
  "georgians:siege": "想象：在上斯瓦涅季（სვანეთი）的一个村庄，劫掠者沿着山谷上来了。各家爬进每座房屋旁矗立的石塔，收起梯子，关上门。男人们从窄窗里射箭；女人们在上层储存了水、奶酪和粮食。他们等了好几天，一起低声用三个声部唱歌，给自己壮胆。劫掠者离开后，村里教堂的钟声响了。",
  "georgians:triumph": "想象：长久的战斗之后，男人们回到卡赫季的一个村庄，女人们在葡萄园边迎接他们。那晚摆开了“苏普拉”（სუფრა）宴席：面包、奶酪、烤肉，还有从陶罐克韦夫里（ქვევრი）中倒出的葡萄酒。祝酒人“塔马达”（თამადა）一杯接一杯地祝酒——敬归来的人，敬没能归来的人，敬土地和葡萄藤——男人们以古老的歌谣回应，三个声部交织，直到天明。",
  "georgians:build": "姆茨赫塔（მცხეთა）的斯维特次霍韦利主教座堂（სვეტიცხოველი）在11世纪由大师阿尔苏基泽（არსუკიძე）重建。格鲁吉亚人讲述着一个关于它的悲伤传说：国王嫉妒心极重，不愿别人再拥有这样一座教堂，便下令砍掉大师的右手。无论此事真假，教堂墙上刻着一只握着矩尺的手，旁边写着：上帝的仆人阿尔苏基泽之手。",
  "georgians:voyage": "10世纪末，以约安内（იოანე）和他的儿子埃夫提米（ექვთიმე）为首的格鲁吉亚修士们西行远赴阿索斯圣山（Ἄθως），渡过黑海和爱琴海。约980年，他们在那里创建了伊维隆修道院（ივერთა მონასტერი），即“格鲁吉亚人的修道院”。埃夫提米毕生把书籍译成格鲁吉亚文，好让家乡的修士能够阅读。修士们给家乡寄信，为留在身后的家人点起蜡烛。",
  "georgians:festival": "每年九月，格鲁吉亚人从卡赫季（კახეთი）各地来到阿拉韦尔迪（ალავერდი）主教座堂过“阿拉韦尔多巴节”（ალავერდობა）。他们在古老城墙周围的草地上扎营，带来羊羔和葡萄酒，一连庆祝好几天。有赛马、摔跤、歌唱和舞蹈；山村里的人带来自己的歌。过去这个节日几乎持续一周，正是葡萄收获开始的时候。",
  "georgians:games": "在古里亚（გურია），复活节星期天，两个村子要玩“列洛布尔季”（ლელო ბურთი）——一种用沉重皮球进行的比赛。神父为球祝福，然后数百名男子，有时是全村人，拼抢着要把球带过一条小溪，送进对方的田里。没有位置分工，几乎没有规则。获胜一方把球带回家时，会把它放在当年去世的一位村民的坟上，以示敬意。",
  "georgians:drought": "想象：卡赫季（კახეთი）一个干旱的夏天，山坡上的葡萄藤正在枯萎。全村人登上山顶的圣乔治小教堂，带着面包、一只羊和去年克韦夫里（ქვევრი）里的葡萄酒。神父祈祷，男人们用三个声部唱起一首缓慢的圣歌，大家一起在草地上吃饭。傍晚走回家时，他们望着高加索山上空，寻找哪怕一朵云。",
  "georgians:quake": "想象：在高山上的拉恰（რაჭა）的一个村庄，一天傍晚，地底传来一阵低沉的隆隆声。石屋开裂，教堂穹顶裂开，岩石滑落到路上。邻居们借着提灯的光用手互相刨救。早上，神父在露天主持礼拜，幸存者们用三个声部唱起葬礼挽歌，歌声在山谷中回荡。",
  "georgians:winter": "想象：冬天，大雪把图舍季（თუშეთი）和斯瓦涅季（სვანეთი）的村庄隔绝好几个月。一家人聚在石屋的炉边，楼下的牛为楼上的人供暖。他们修理工具，纺羊毛，讲圣乔治（წმინდა გიორგი）的故事。夜里男人们唱起古老的劳动歌和狩猎歌，祖母们教小孩子唱低声部。寒冷漫长，但歌声总是三个声部。",
  "georgians:plague": "想象：夏天，瘟疫传到了第比利斯（თბილისი），城市空了。能走的人家逃到山里的村庄；其他人关上门等待。神父们捧着圣像、提着香炉走过窄巷，吟唱祷文。幸存者在锡奥尼（სიონი）主教座堂点起蜡烛，在墙上刻下小小的十字架。后来老人们说：我们活了下来，是因为我们没有忘记一起祈祷。",
  "georgians:wedding": "格鲁吉亚婚礼是一场盛大的“苏普拉”（სუფრა）。宾客们带来葡萄酒和面包；祝酒人“塔马达”（თამადა）整夜主持几十轮祝酒：敬新人，敬父母，敬祖先，敬友谊。祝酒间隙，宾客们用三声部和声歌唱，年轻人起舞，男子骄傲挺拔，女子滑行般仿佛脚不沾地。古老的“马克鲁利”（მაყრული）歌曾用来迎接新娘的队伍。",
  "huns:siege": "普里斯库斯（Πρίσκος）记载，约467年，一群匈人和哥特人被罗马军队困在色雷斯（Θρᾴκη）的一处洼地里。他们被团团围住，没有食物，便派使者表示：若能得到耕种的土地，就投降。罗马人答应了，把他们分成几群，然后反戈相向。普里斯库斯把这讲成一场背信弃义；对死在那里的匈人来说，这是远离草原的饥饿家庭最后的抵抗。",
  "huns:triumph": "449年，来自君士坦丁堡（Κωνσταντινούπολις）的使节普里斯库斯（Πρίσκος）看到阿提拉回到他在平原上的村庄。年轻女子们排成行出来迎接，走在由其他女子高举的白色长亚麻纱幔下，唱着匈人的歌。他经过大臣奥涅格西乌斯（Ὀνηγήσιος）的家时，奥涅格西乌斯的妻子端着盛有食物和酒的银盘出来，阿提拉就在马上吃了。整个村子充满了音乐与欢乐。",
  "huns:build": "普里斯库斯（Πρίσκος）描述了449年阿提拉在匈牙利平原上的村庄：一座带塔楼的大木屋，用打磨光滑的木板建成，接合得天衣无缝，看上去像一整块，四周围着木栅栏。附近，奥涅格西乌斯（Ὀνηγήσιος）让一位来自西尔米乌姆的被俘建筑师建了一座石砌浴室，建筑师本盼着凭这项工程获得自由，结果却被留下当了浴室管理员。其余一切都是木头的，由匈人工匠从远方运来。",
  "huns:voyage": "想象：约370年，匈人渡过伏尔加河，带着全部家当穿越草原西进。盖着毛毡的大车载着老人、孩子和妇女；马、牛、羊群绵延数里。每晚营地都围成一圈。罗马作家说他们突然出现，仿佛从天而降。对这些家庭来说，这是一条通往无人放牧过的草场的漫长而缓慢的路。",
  "huns:festival": "449年在阿提拉的宴会上，普里斯库斯（Πρίσκος）看到宾客们按品级依次用金杯银杯祝酒。夜幕降临，火把点起，两位歌者站在阿提拉面前，唱起他们为他的胜利和勇气编写的歌。宾客们聚精会神地听着；有人兴高采烈，有人潸然泪下——老人们怀念着自己再也无法骑马奔赴的战斗。然后一个弄臣走进来，所有人都笑了。",
  "huns:games": "想象：平原上的一个夏日，年轻的匈人举行比赛。罗马作家说，匈人仿佛粘在马背上，吃饭甚至睡觉都在马上。骑手们疾驰过靶子，在鞍上转身向后放箭；另一些人全速飞驰，从地上抄起一支长矛。老战士们当裁判，又喊又笑。最好的骑手得到一匹马和一杯马奶。",
  "huns:drought": "想象：树木年轮告诉我们，5世纪的匈牙利平原经历了严重干旱的年份。匈人家庭看着草枯萎、河流萎缩。畜群日渐消瘦，男人们每天都要骑得更远去找牧场。一些家庭在村庄附近定居下来，用畜产换取粮食。长老们说天空发怒了；年轻人夜里听着萨满的鼓声，等待雨水。",
  "huns:quake": "447年1月，正当匈人军队在巴尔干推进时，一场大地震袭击了君士坦丁堡（Κωνσταντινούπολις），震塌了大段城墙和五十七座塔楼。城防已毁的消息在匈人各营飞速传开。但市民们日夜赶工，仅用约六十天就重建了城墙。骑马前去察看缺口的匈人骑手只看到了崭新的石墙，只好折返。",
  "huns:winter": "想象：冬天多瑙河封冻，匈人骑手可以踏冰而过。平原上，一家家人躲在毛毡帐篷和木屋里，裹着毛皮——据一位罗马作家说，还有田鼠皮。马匹用蹄子刨开积雪寻找干草。夜里，老人们讲述东方草原和它无尽冬天的故事，孩子们紧紧依偎在一起。",
  "huns:plague": "452年，匈人入侵意大利，但他们的军队病倒了。编年史家伊达提乌斯写道，匈人遭受了上天降下的疾病与饥荒，又被东罗马皇帝的士兵攻击。曾意气风发翻越阿尔卑斯山的匈人战士，如今每天都在埋葬同伴。他们翻山回家，人更少了，也更沉默了，没什么可庆祝的。",
  "huns:wedding": "449年的旅途中，普里斯库斯（Πρίσκος）来到一个村庄，阿提拉在那里停留，迎娶一个名叫埃斯卡姆（Ἐσκάμ）的人的女儿，尽管他已有许多妻子。普里斯库斯没有描述婚礼本身，但他见识了匈人如何宴饮：女子们在亚麻纱幔下排成行歌唱，食物盛在银盘里端上，葡萄酒和大麦酿的“卡莫斯”（κάμος）尽情畅饮。想象：新娘骑马前往丈夫的营地，全村人在她身后歌唱。",
  "cumans:siege": "想象：1237年，蒙古骑兵在开阔的草原上截住了一个库曼氏族。无处可逃，各家便把大车围成一圈，车轮之间用铁链相连，妇女、孩子和畜群都在圈内。男人们从车缝间放箭。皮囊里的水越来越少；马匹日渐虚弱。第三夜，老人们向祖先歌唱，年轻人准备最后一次冲出去。",
  "cumans:triumph": "想象：一次长途袭掠之后，库曼骑手们赶着马、带着布匹穿过草原回家。营地的人都出来迎接：孩子们跟在旁边跑，女人们唱歌，打开一囊新鲜的马奶酒。当晚设宴，一位歌者拉着科布兹琴（kobyz）讲述当日的事迹。骑手们把礼物送给老人和寡妇。最勇敢的战士获得第一杯酒的荣耀。",
  "cumans:build": "在黑海北岸的草原上，库曼人在祖先的坟丘上竖起石像：用石灰岩雕成的男人和女人，双手捧杯，发辫、腰带和耳环都刻画得一丝不苟。各家齐心协力开石、运石，把它立在古坟上。旅行者写道，库曼人在石像前供奉祭品。许多石像至今仍立在那里，越过草地向东眺望。",
  "cumans:voyage": "1239年，为躲避蒙古人，科腾率领约四万户库曼人向西进入匈牙利，带着大车、马匹和牛群翻越喀尔巴阡山。编年史家托雷马焦雷的罗杰（Rogerius）描述了这支长长的队伍从山口蜿蜒而下的情景。他们在大平原上分得了土地。好几代人里，库曼人保留着自己的语言、祈祷和歌谣，他们的后裔至今仍记得自己来自草原。",
  "cumans:festival": "想象：春天，母马产下第一批奶时，库曼营地要举行新马奶酒节。所有人聚在首领的毡房前；长老们把第一杯洒在地上敬献神灵和祖先，然后传杯共饮。有歌声，有科布兹琴和冬不拉，年轻人跳起舞来。漫长的冬天过后，白色的奶意味着生命正回到草原。",
  "cumans:games": "想象：在一次库曼人的聚会上，骑手们玩“叼羊”（kokpar）：一只山羊的尸体被扔进场地，几十名骑手争抢着抓住它，拖过草地，扔进球门。马匹相撞，人从鞍上探身，观众欢声雷动。另一些人进行长距离赛马，或在马背上摔跤，想把对方拽下马来。获胜者得到马匹和歌颂。",
  "cumans:drought": "想象：黑海北岸草原上一个干旱的夏天。井水很浅，草在脚下噼啪作响，每个骑手身后都扬起尘土。库曼人家把畜群赶向河边，但别的氏族也来了。长老们会面商议分水。夜里，一位萨满击鼓，呼唤蓝天腾格里降雨。人人都在等待，望着地平线上的云。",
  "cumans:quake": "想象：库曼商人南下到克里米亚海岸卖马和毛皮。一天早上大地震动；石屋开裂，墙倒在街上，海水从海滩退去。库曼人牵着马跑到空地上。后来回到草原，他们告诉家人坚实的大地如何像水一样流动，老妇人们做着驱邪的手势。",
  "cumans:winter": "想象：一场“白灾”（jut）——致命的严冬——降临库曼人。雨水在雪上冻成一层冰壳，马匹无法刨开它吃到草。一天又一天，牲畜日渐虚弱、死去。一家家人聚在毡房里烧牛粪，用自己的外衣裹住羊羔。男人们骑马出去，寻找风吹掉冰层的牧场。春天来时，他们清点剩下的，重新开始。",
  "cumans:plague": "想象：一个库曼营地爆发了疾病。萨满整夜绕着帐篷击鼓，驱赶恶灵。病人的家属把毡房搬离其他人，谁也不共用一只杯子。骑手们把警讯送到邻近的营地。疾病过去后，人们烧掉死者的被褥，在坟丘上竖起一尊新的石像。",
  "cumans:wedding": "想象：一位库曼新娘从娘家的营地被送往新郎的营地。临行前，她为父母和姐妹唱起告别歌，人人都流下眼泪。到了新郎的毡房，她的脸被面纱遮住；一位歌者即兴唱诗，把她介绍给每一位亲属，直到最后才揭开面纱。然后是马奶酒、肉和音乐，年轻人玩游戏直到天明。",
  "tatars:siege": "1236年秋，蒙古大军包围了伏尔加保加尔人——喀山鞑靼人的祖先——最大的城市比利亚尔（Биләр）。城中的商人、陶工和农民挤在木墙和壕沟之后，坚守了四十五天。城破之后，被付之一炬。幸存者向北逃进森林，重建家园。鞑靼传说至今仍讲述着那座失落的城市和埋在地下的钟。",
  "tatars:triumph": "想象：一个鞑靼村庄的骑手们结束了漫长艰苦的征战回家。村口，女人们捧着面包、盐和绣花毛巾等候，孩子们跑去牵马。当晚设宴：蜂蜜、羊肉、甜点恰克恰克（чәкчәк）。一位老人吹起库赖笛（курай），男人们唱起叙事歌“拜耶特”（бәет），好让这一天被人铭记。",
  "tatars:build": "鞑靼人家需要盖房子、谷仓或清真寺时，村里就举行“厄梅”（өмә）——互助劳动日。邻居们带着斧头和马匹前来；男人们砍削原木、立起墙壁，女人们用大锅做饭、唱歌。秋天有拔鹅毛的厄梅，姑娘们排着队把鹅送到河边。之后大家一起吃饭，年轻人随着手风琴起舞。",
  "tatars:voyage": "想象：春天，一位鞑靼商人带着前往布哈拉（Бохара）的商队离开喀山（Казан），驮着皮革、毛皮和铁器。几周里，骆驼缓缓走过草原和沙漠，经过一口口水井和一座座驿站。他每天礼拜五次，用阿拉伯字母写家书。当布哈拉的蓝色穹顶出现在地平线上时，整个商队欢呼起来。秋天他将带着丝绸和茶叶返回。",
  "tatars:festival": "纳尔杜甘节（Нардуган）是鞑靼人的冬至节，在太阳转向春天时到来。年轻人戴上面具、反穿羊皮袄，挨家挨户唱歌说笑；人们送给他们糖果和点心。姑娘们把蜡滴进水里占卜，或在窗外偷听一个字眼，以此预言未来丈夫的名字。然后是坐雪橇和随着手风琴跳舞，直到深夜。",
  "tatars:games": "鞑靼孩子们玩“白杨树，蓝杨树”（Ак тирәк, күк тирәк）。两排人手拉手面对面站着；一方喊出一个名字，被叫到的孩子就全速冲向对面那排，想冲开相连的手。冲开了，他就带一个人回来；冲不开，他就留在那边。游戏在尖叫和笑声中继续，直到一排人没了，太阳也落山了。",
  "tatars:drought": "1891年，伏尔加河沿岸雨水断绝，庄稼死在田里。在鞑靼村庄，一家家人吃掺了谷糠、橡子和藜草的面包；牛几乎白送般被卖掉，许多孩子没能熬过冬天。清真寺为穷人募集粮食，喀山（Казан）的商人筹钱开设粥棚。老人们称之为“饥荒之年”（ачлык елы），余生都只是轻声谈起它。",
  "tatars:quake": "想象：克里米亚一个村庄的鞑靼人家在夜里被大地的轰鸣惊醒。石墙开裂，一座宣礼塔倒塌，早上他们发现泉水流出了泥浆。伊玛目把人们召集到空地上。一家家人在果园里露营了一周，一起做饭、祈祷，直到大地不再颤动。然后他们一石一石地重建。",
  "tatars:winter": "想象：一场暴风雪“布兰”（буран）横扫伏尔加河畔的一个鞑靼村庄。雪堆到窗户，通往喀山（Казан）的路好几天都找不到。木屋里，一家人围坐在大炉子旁，喝着奶茶，吃着恰克恰克。祖母讲起森林精灵舒列列（Шүрәле）的故事，孩子们又怕又乐地打着哆嗦。早上，他们挖出一条通往谷仓的路。",
  "tatars:plague": "想象：1346年，一场可怕的疾病沿伏尔加河（Идел）蔓延，商贸城镇陷入寂静。在一处鞑靼聚落，各家关上了门，毛拉挨家挨户为垂死者念诵祷文。死者按照信仰的要求被迅速清洗安葬，但死的人实在太多。幸存者把食物放在病人的门口。集市空了，商队不再来了。",
  "tatars:wedding": "在鞑靼婚礼上，毛拉在新娘家诵读婚约“尼卡赫”（никах）。几天后，新郎驾着装饰一新的雪橇或马车来接她，她的亲戚们拦住道路，直到得到礼物才放行。她到来后的第二天早上，年轻的妻子挑着扁担和水桶走向泉边——这叫“水路”（су юлы）——往水里丢一枚硬币，从此属于她的新村庄。",
  "golden-horde:siege": "1395年，帖木儿的大军席卷钦察人的土地，抵达伏尔加河畔的萨莱（سراي）。逃不了的人家躲在城中的房屋和花园里，躲在从未为战争而修筑的墙后。城市遭到洗劫焚烧；工匠们被掳走。幸存者回到一座满是灰烬和碎瓷砖的城市。这座伟大的都城再也没能恢复，草原慢慢把它收了回去。",
  "golden-horde:triumph": "想象：长途征战之后，可汗的大军回到草原。骑手们先行飞奔到营地，高喊着报捷。巨大的白色大帐敞开，纳卡拉鼓擂响，卡尔奈长号吹起。马奶酒从皮囊中流出；烤着羊和马。歌者和说书人讲述战斗的经过，战士们从可汗手中接过赏赐的马匹、丝绸和白银。",
  "golden-horde:build": "14世纪30年代，伊本·白图泰（ابن بطوطة）来到伏尔加河畔的新萨莱（سراي），称它为最美丽的城市之一，大到步行穿城要半天。钦察、蒙古、切尔克斯、罗斯和拜占庭商人各有自己的街区，有市场、清真寺，还有运河浇灌的花园。建造者用烧砖和釉面瓷砖建起了它——一座在同一处扎下根来的草原之城。",
  "golden-horde:voyage": "1334年，伊本·白图泰（ابن بطوطة）随月即别汗之妻、拜占庭皇帝之女巴雅伦同行，她要回君士坦丁堡分娩。她的车队带着五百名骑手、女奴和仆从横穿钦察草原，钦察厨师在移动的厨房里为她做饭。到了边境，钦察护卫折返。伊本·白图泰写道，草原被抛在身后时，公主哭了。",
  "golden-horde:festival": "伊本·白图泰（ابن بطوطة）在月即别汗的营地过了开斋节（عيد الفطر）。他写道，可汗身披精美铠甲率军出行，可敦们坐在覆盖丝绸的车里，随后在一座金色织锦的大帐中举行盛宴。马奶酒和肉分给每个人，可汗坐在宝座上，妻子们在旁。整整一天，草原上乐声不绝。",
  "golden-horde:games": "想象：在一次钦察人的聚会上，各氏族最好的骑手在开阔的草原上进行数公里的长距离赛马，骑师是身材矮小轻巧的男孩，骑着无鞍马。摔跤手在可汗的大帐前角力，射手们射靶，骑手们全速疾驰中从地上抓起硬币。人群高喊着各自冠军的名字。获胜者得到马匹、长袍和可汗亲手递上的一杯马奶酒。",
  "golden-horde:drought": "想象：夏雨没有降临钦察草原。草变成褐色，湖泊缩成一层盐壳，畜群日渐虚弱。一家家人把车向北赶往森林，或赶往大河，寻找牧场。夜里，他们向腾格里和真主祈祷，往地上洒一点奶。第一场暴雨终于来临时，人人都笑着跑进雨中。",
  "golden-horde:quake": "想象：一天傍晚，克里米亚小城索尔哈特的钦察商人感到大地震动。宣礼塔摇晃，灰泥脱落，人们跑上街头。骆驼在驿站里吼叫。到早上，清点损失：几座房屋倒塌，一口井裂开，清真寺的穹顶裂了缝。城里人互相帮助，可汗的总督派来石匠重建。",
  "golden-horde:winter": "伊本·白图泰（ابن بطوطة）在冬天穿越钦察草原。他写道，他穿了三件皮袄、两条裤子和毛皮衬里的靴子，洗脸时水在脸上就结了冰。不靠人帮忙，他连马都爬不上去。钦察旅伴们笑着帮他，他踏着冰渡过封冻的伏尔加河到达萨莱（سراي），冰封的河面上雪橇来来往往。",
  "golden-horde:plague": "1346年，包围商港卡法（Kefe）的钦察军队遭到瘟疫袭击。士兵成千上万地病倒死去；营地里满是死者和垂死的人。加布里埃莱·德穆西斯后来写到尸体如何被抛过城墙。对草原上的家庭来说，那些没能回来的战士永远不会被遗忘；疫病沿着商路传进了草原上的每一座城镇。",
  "golden-horde:wedding": "想象：一位钦察新娘离开父母的营地，唱着告别歌，母亲在一旁哭泣。她的嫁妆装在一辆装饰华丽的车上随行。到了新郎的营地，她被藏在帘子后面，直到一位歌者一段一段地唱诗，把她介绍给新郎的每一位亲属，亲属们送上礼物。然后帘子揭开，斟上马奶酒，年轻人玩耍歌唱，直到深夜。",
  "berbers:siege": "想象：士兵们在卡比利亚（ⵜⴰⵎⵓⵔⵜ ⵏ ⵍⵇⴱⴰⵢⴻⵍ）一道山脊上的阿马齐格村庄下扎营。小路被监视，粮食运不进来，山下的泉水也够不着。女人们夜里沿着隐秘的小道把水背上来；男人们端着老式火枪守住狭窄的入口。村民们吃无花果干和橡子面包。傍晚，女人们唱起“伊兹兰”（ⵉⵣⵍⴰⵏ）——鼓舞勇气的短歌，男人们在墙头应和。",
  "berbers:triumph": "想象：图阿雷格男子们骑着白骆驼穿越沙漠回家，脸上蒙着靛蓝色的面纱。营地里，女人们跑出来发出颤音欢呼；那一夜是“阿哈尔”（ahal）——音乐与求爱之夜。一位女子在伊姆扎德琴（ⵉⵎⵣⴰⴷ）上拉动琴弓，其他人唱歌，敲着滕德鼓（ⵜⴻⵏⴷⴻ）。骑手们让骆驼绕着圈子起舞。一个男人只有被女人们唱进歌里，才算得到了赞美。",
  "berbers:build": "在小阿特拉斯山，阿马齐格村庄在岩石高处建起“伊古达尔”（ⵉⴳⵓⴷⴰⵔ）——设防的集体粮仓。大家一起砌起石墙；每家分得一个小房间，存放粮食、橄榄油、蜂蜜和文书，用一把雕花木钥匙打开。一位守护人“拉明”（lamin）看守大门，里面挂着成文的规约。危难时刻，粮仓是整个山谷最安全的地方。",
  "berbers:voyage": "每年秋天，阿伊尔山的图阿雷格人（ⵉⵎⵓⵀⴰⵖ）踏上“阿扎莱”（azalai）盐队之旅，前往比尔马绿洲，要在泰内雷沙漠中走上好几周。数百头骆驼排成长队；男人们靠星辰、沙丘和沙子的颜色辨认方向。他们驮去小米和布匹，换回盐和椰枣。当比尔马的绿色棕榈终于出现在地平线上时，男人们唱起了歌。",
  "berbers:festival": "1月12日或13日，阿马齐格家庭庆祝农历新年“耶纳耶尔”（ⵢⴻⵏⵏⴰⵢⴻⵔ）。女人们做七种蔬菜的古斯古斯，或在一道菜里藏一颗椰枣核：谁吃到，谁就一整年好运。孩子们挨家挨户讨糖果和干果。房屋打扫干净，灶火更新，各家祈求丰收。",
  "berbers:games": "想象：在沙漠中的一个图阿雷格节日上，年轻男子们骑着骆驼在沙地上赛跑，女人们围坐成一圈，敲着滕德鼓（ⵜⴻⵏⴷⴻ）唱歌。骑手们疾驰而去，又折回来绕着女人们转圈，炫耀自己的骆驼和靛蓝长袍。最好的骑手赢得的不止是奖品：还有女人们歌中的赞美，那些歌会在篝火旁被传唱好几个月。",
  "berbers:drought": "20世纪70年代，连年干旱袭击了撒哈拉和萨赫勒。图阿雷格（ⵉⵎⵓⵀⴰⵖ）牧人眼看着自己的骆驼和山羊死在干涸的井边；许多家庭离开沙漠去了城镇，或远走他乡流亡。远离营地的年轻人学会了吉他，唱起“阿苏夫”（ⴰⵙⵓⴼ）——思念与孤独，唱沙漠，唱失去的家人。这些歌成了一种新的音乐。",
  "berbers:quake": "1960年2月29日午夜前，斋月期间，一场地震袭击了阿加迪尔（ⴰⴳⴰⴷⵉⵔ）城。十五秒内，大半座城市倒塌，山上的古老城堡也坍塌了。约一万五千人遇难，许多人死于睡梦中。苏斯（ⵙⵓⵙ）地区阿马齐格村庄的人们下山寻找亲人，刨挖瓦砾。城市后来在更南边重建。",
  "berbers:winter": "想象：在高阿特拉斯山（ⴰⴷⵔⴰⵔ ⵏ ⴷⵔⵏ），大雪封住了山口，村子被隔绝了好几周。土房里，一家人睡在牲畜旁取暖。女人们在火边的织机上织地毯，唱着“阿希杜斯”（ahidus）歌，男人们修理工具，大家都喝着甜薄荷茶。秋天的大麦和肉干必须撑到春天。骡道重新打通时，全村一起庆祝。",
  "berbers:plague": "想象：瘟疫的消息传到德拉河谷的一座阿马齐格土堡（ksar）。长老们对外人关闭大门；不许任何商队进入。女人们在屋里焚烧草药，教法师（فقيه）日夜在清真寺诵读《古兰经》（القرآن）。有人病倒时，由一位家人照料，其余的人保持距离。全村都在等待，倾听风中传来的消息。",
  "berbers:wedding": "九月，伊米勒希勒（ⵉⵎⵉⵍⵛⵉⵍ）的艾特·赫迪杜人（ⴰⵢⵜ ⵃⴷⵉⴷⵓ）举行著名的婚姻集会。传说来自敌对氏族的一对恋人伊斯利（ⵉⵙⵍⵉ）和蒂斯利特（ⵜⵉⵙⵍⵉⵜ）被禁止成婚，哭得太多，泪水汇成了两座湖。如今，年轻男女在这个集会（moussem）上自由相会，彼此选择，登记结婚，本迪尔鼓（bendir）敲响，阿希杜斯舞者摇摆起舞。",
  "ethiopians:siege": "想象：劫掠者进了山谷，哈贝沙村民们把牛群赶上、把粮食背上“安巴”（አምባ）——一座四面绝壁的平顶山。他们在身后收起绳索。水装在罐里吊上来；神父带来了用布包着的教堂圣约柜“塔博特”（ታቦት）。几周里，他们在山顶等待，祈祷，唱诗篇，望着山下的火光。",
  "ethiopians:triumph": "想象：哈贝沙战士们战后回到村庄。女人们发出高亢的颤音欢呼“埃莱尔塔”（እልልታ）出来迎接。男人们一个接一个上前表演夸功吟唱“富凯拉”（ፉከራ）：他们跺脚，挥舞长矛，高喊自己的事迹和家族名号。人群以喊声回应。那晚斟上蜂蜜酒“特吉”（ጠጅ），一位游吟歌手“阿兹马里”（አዝማሪ）为每个人即兴作歌。",
  "ethiopians:build": "3至4世纪，在阿克苏姆（አክሱም），哈贝沙石匠雕凿出高如塔楼的巨大花岗岩方尖碑，上面刻着假门假窗，像一座座多层楼房。数百名工人用滚木把它们从采石场拖出来，借助斜坡和绳索将其竖起。最大的一座高逾三十米，倒下断裂了，也许就是在竖立时倒下的。它的碎块至今仍躺在倒下的地方，就在那些依然矗立的石碑旁边。",
  "ethiopians:voyage": "《列王荣耀》（ክብረ ነገሥት）讲述示巴女王马克达（ማክዳ）如何带着满载黄金、香料和宝石的驼队从她的国土前往耶路撒冷，去会见所罗门王，学习他的智慧。她住了六个月，回国时怀着一个儿子——孟尼利克（ምኒልክ）。对哈贝沙人来说，她的旅程是一个漫长故事的开端，由神父讲述，由阿兹马里传唱。",
  "ethiopians:festival": "哈贝沙新年“恩库塔塔什”（እንቁጣጣሽ）在九月，正值长雨季结束、黄色的梅斯克尔花开满山坡之时。穿着白色新裙子的女孩们挨家挨户唱《阿贝巴耶霍什》（አበባየሆሽ），献上花束或图画；男孩们拿着自己画的画。各家给她们面包或硬币，大家一起吃饭。这是一个崭新开始与绿色田野的节日。",
  "ethiopians:games": "圣诞节“根纳”（ገና），哈贝沙青年玩一种也叫“根纳”的游戏：一种类似曲棍球的比赛，用弯曲的棍子和木球，在开阔的田野上一直玩到黄昏。传说牧羊人正在玩这个游戏时，听到了基督降生的消息。村中长老们观战呼喊，输的一方有时会唱戏谑的歌，之后大家一起享用盛宴。",
  "ethiopians:drought": "想象：在沃洛（ወሎ）高原的一个哈贝沙村庄，短雨季“贝尔格”（belg）的雨落了空，如今大雨季的雨也迟迟不来。田里的苔麸（ጤፍ）幼苗发黄。女人们每天早上望天，男人们每天晚上清点仓里剩下的粮食。神父们抬着塔博特绕教堂行进；全村斋戒祈祷。云终于聚起来时，人们哭了。",
  "ethiopians:quake": "想象：在东非大裂谷边缘的安科贝尔（አንኮበር），一天夜里大地震动。石墙开裂，教堂的钟自己响了起来，人们从屋里跑进寒夜。神父们带领大家祈祷。早上，各家发现牛不见了，有几户房屋毁了。邻居们送来英杰拉饼（እንጀራ），帮忙重建。老人们说，这里的大地从不安宁。",
  "ethiopians:plague": "1887年，牛瘟传到红海沿岸，蔓延进哈贝沙高原。两年之内，大部分牛都死了。对靠牛犁地的农民来说，这是一场浩劫：田地无法耕种，牛奶消失，饥荒随之而来。一家家人为牲畜痛哭，如同为亲人痛哭。在一些村子里，男人们亲自拉犁。那段时期至今仍被铭记为“凶年”（ክፉ ቀን）的开端。",
  "ethiopians:wedding": "在哈贝沙婚礼上，新郎和他的伴郎们“米泽”（ሚዜ）唱着歌来到新娘家。她的家人关上大门，双方对唱戏谑的歌，直到放新郎进去。女人们的颤音欢呼响起，凯贝罗鼓（ከበሮ）敲响，人们耸动肩膀跳起“埃斯基斯塔”舞（እስክስታ）。宴席上，大家吃着英杰拉配辣炖鸡，喝着蜂蜜酒，直到深夜。",
  "malians:siege": "想象：稀树草原上的一座曼丁小城被它的“塔塔”（tata）——一道厚厚的晒干土墙——环绕着。骑兵已将它包围，农民们带着粮食和山羊挤进城里。夜里守军在墙上守望，鼓声不停，让敌人知道他们醒着。格里奥（ߖߋߟߌ）在城门口歌唱祖先的事迹。粮食越来越少；他们仍然坚守。",
  "malians:triumph": "《松迪亚塔》（ߛߎ߲ߖߊߕߊ）史诗讲述，约1235年基里纳之战后，曼丁各氏族聚集在库鲁坎·富加（ߞߎߙߎߞߊ߲ߝߎߜߊ）。松迪亚塔的格里奥巴拉·法塞凯站在人群前歌颂他；各氏族首领把长矛插在国王面前的地上。音乐响了好几天，巴拉丰木琴叮咚作响，各家回到了祖辈的土地。",
  "malians:build": "每年春天雨季来临前，杰内（ߘߖߋߣߋ）的人们都要重新涂抹他们的大清真寺——世界上最大的泥建筑。前几天，男人们在坑里把泥和稻壳混合；到了那天，数百名年轻人踩着棕榈木横梁爬上墙，其他人把一筐筐泥往上递，争先恐后地要最先完成。女人们运水，长老们指挥，鼓声和歌声让每个人都动个不停。",
  "malians:voyage": "欧麦里（العمري）写道，曼萨·穆萨（منسا موسى）在开罗（القاهرة）告诉他，他的前任阿布巴卡里想知道西边的大洋尽头在哪里。他派出两百艘船；只有一艘回来，说其他船都在一股巨大的洋流中消失了。于是国王亲自率两千艘船出发，留下穆萨治国。此后再也没人见过他。曼丁的格里奥们至今仍在猜想他找到了怎样的土地。",
  "malians:festival": "每年雨季前选定的一天，桑城（ߛߊ߲）的人们举行“桑凯蒙”（ߛߊ߲ߞߋ ߡߐ߲）——在圣池中集体捕鱼。信号一响，数百名男女老少带着渔网和葫芦冲进水里，一起捕鱼好几个小时。鼓声敲响，女人们歌唱。之后，每家都分得一份渔获，面具舞者起舞。",
  "malians:games": "想象：收获之后，一个曼丁村庄的年轻人在沙圈里摔跤。金贝鼓（ߖߋ߲ߓߋ）和敦敦鼓（dundun）把一对对选手召进场，摔跤手们先绕着彼此跳舞，然后才交手。姑娘们拍着手，为自己中意的小伙子唱戏谑的诗句。冠军把对手摔倒时，格里奥（ߖߋߟߌ）高喊他家族的颂名，人群向前涌去。",
  "malians:drought": "20世纪70年代初，萨赫勒地区连续数年雨水断绝。曼丁农民眼看着小米在田里枯萎；尼日尔河（Jɔliba）萎缩，鱼越来越少，牧人的牛死在干涸的路上。许多家庭离开村庄去了城镇。女人们每天要走好几个小时去找水。格里奥们把那些年编成歌，好让年轻人知道父母曾熬过了什么。",
  "malians:plague": "想象：在一个曼丁村庄，旱季里一场热病在各个院落间蔓延。长老们把孩子们送到另一个村子的亲戚家。医者采集树叶和草根；伊玛目夜里诵读祷文。有人死去时，女人们哀嚎，男人们一起挖坟。格里奥在葬礼上轻声歌唱。热病结束后，村里举行献祭和感恩宴。",
  "malians:wedding": "在曼丁婚礼上，新娘由娘家的女人们打扮好几天，手脚染上指甲花，头发编成辫子。婚礼当天，格里奥（ߖߋߟߌ）歌颂两个家族，一代代追溯祖先的名字，科拉琴（ߞߐߙߊ）和巴拉丰木琴在旁伴奏。宾客们送上礼物，格里奥把每一份都高声宣布。然后新娘在歌舞中被送往丈夫的院落。",
  "hausa:siege": "想象：一支敌军在卡诺（كَنُو）城外扎营。巨大土墙“加努瓦”（ganuwa）上的城门紧闭，乡下的村民带着粮食和山羊挤进城里。城墙内圈着农田和水井，所以城市可以自给数月。每夜守军在墙上守望，卡兰古鼓（kalangu）沿着城墙“说话”。城里，女人们磨粮，孩子们挤在一起睡。",
  "hausa:triumph": "想象：一座豪萨小镇的男人们苦战之后骑马回家。女人们发出高亢的颤音欢呼出来迎接，赞颂歌手“马罗卡”（maroka）跟在马旁奔跑，高喊每位骑手的家族名号和事迹。卡兰古鼓在城门口应和。院落里，女人们煮米饭和炖菜，大家分享布匹和可乐果作为礼物。今天被马罗卡赞颂的人，将在歌中被铭记多年。",
  "hausa:build": "《卡诺编年史》说，约12世纪，萨尔基吉吉马苏开始修建卡诺（كَنُو）的城墙，后来的统治者又将其扩建。成千上万的人一起劳作：他们挖出深沟，把土堆成高达数米的城墙，再抹上泥浆。建造者边干边唱，城墙最终环绕了城市和农田。部分城墙至今仍然矗立。",
  "hausa:voyage": "几百年来，豪萨朝圣者步行前往麦加（مكة）朝觐，穿越萨赫勒和苏丹到达红海。这段旅程可能要走好几年：他们沿途停下来种地、做买卖以支付路费，有些人再也没有继续前行，在沿途建起了豪萨村庄。当他们终于看见红海、渡海到达阿拉伯时，喜极而泣。他们的后裔至今仍生活在那条路上。",
  "hausa:festival": "每年在索科托河（Sakkwato）畔的阿尔贡古，成千上万的渔民在岸边等待信号。信号一响，他们带着渔网和葫芦浮子跃入水中，徒手捕捉巨大的尼罗河鲈鱼。鼓手在岸上击鼓，赞颂歌手高喊获胜者的名字，载着乐师的船只在河上来往。渔获过秤之后，全镇大摆宴席。",
  "hausa:games": "豪萨拳击“丹贝”（Dambe）曾是收获季节屠夫行会之间的比赛。拳手有力的那只手缠着绳子；另一只手张开用来防守。拳手们带着护身符出场，鼓手敲出他们村子的节奏，人群齐声呼喊。有人倒地或长老喊停，一个回合就结束。冠军赢得声名和礼物，赞颂歌手为他们作歌。",
  "hausa:drought": "想象：雨迟迟不来，豪萨农民田里的小米停止了生长。井水很浅，女人们天不亮就去排队。伊玛目带领全体在城外求雨；人人都穿着旧衣。各家少吃一点，留下明年的种子。夜里，老人们谈起从前的饥荒，以及祖辈是如何熬过来的。",
  "hausa:plague": "想象：旱季最盛、哈麦丹风吹拂之时，脑膜炎袭击了一座豪萨小镇。孩子和年轻人发烧、脖子僵硬，医者们应接不暇。经师（malam）把《古兰经》（القرآن）经文写在木板上，洗下墨水，给病人喝那水。一家家人彻夜守候。雨季来临，疫病消退，小镇哀悼它的死者。",
  "hausa:wedding": "豪萨婚礼始于两家商定聘礼“萨达基”（sadaki）。婚前几天，新娘的女友们用指甲花“昆希”（kunshi）为她的手脚绘上花纹，为她歌唱。婚约在清真寺缔结，男人们诵读《开端章》（فَاتِحَة）。傍晚，新娘被送往丈夫家，女友们唱着歌，鼓手和赞颂歌手跟随其后。然后是载歌载舞的宴席。",
  "persians:showcase": "伊朗最古老的音乐只能看见，无法听到：埃兰的浮雕上刻着竖琴、管笛和鼓。约公元600年的萨珊宫廷里，歌手巴尔巴德（باربد）为库思老二世（خسرو پرویز）弹奏巴尔巴特琴（بربط），传说他创立了王家调式，并为一个月中的每一天各作一首歌。伊斯兰时代以后，波斯乐师参与了巴格达的音乐艺术，写下了其中大量的乐理。恺加时代，大师们把古老的旋律汇集成“拉迪夫”（ردیف）——达斯特加赫（دستگاه）调式体系的曲库。如今，“阿瓦兹”（آواز）歌手仍伴着塔尔琴（تار）、桑图尔琴（سنتور）、卡曼恰琴（کمانچه）、盖查克琴和奈伊笛（نی）在这些调式中即兴演唱，而由卡尔奈长号和纳卡雷鼓组成的鼓乐楼（نقاره‌خانه）曾在日出和日落时奏响。",
  "persians-early:showcase": "萨珊伊朗（ساسانیان）的音乐是从图像、人名和后世书籍中得知的，而不是从乐谱。塔克-伊-博斯坦（طاق بستان）的岩拱上，王家猎野猪的场景中有女子在船上弹奏竖琴（چنگ），银碗上则刻着琵琶类乐器的弹奏者和舞者。阿拉伯和波斯作家记得库思老二世（خسرو پرویز）的乐师：弹巴尔巴特琴（بربط）唱歌的巴尔巴德（باربد），以及他的对手、竖琴师纳基萨（نکیسا）。据说巴尔巴德的王家“库思老之歌”和有名称的调式传给了巴格达的乌德琴大师，但如今已无一能够演奏。本曲是用一个朴素音阶所作的重构，使用巴尔巴特琴、竖琴、奈伊笛、双管笛、卡尔奈长号、纳卡拉鼓和桑吉钹。",
  "achaemenids:showcase": "阿契美尼德王朝的音乐没有一个音符留存下来；我们所知的来自图像和希腊作家。亚述浮雕展示了在他们之前的埃兰宫廷乐队，有角形竖琴、双管笛和一面鼓。希罗多德（Ἡρόδοτος）写道，在波斯人的祭祀中，一位麻葛（𐎶𐎦𐎢𐏁）吟唱诸神诞生之歌；希腊作者还列出了末代国王宫中受过训练的女乐师。本曲重构了波斯波利斯（𐎱𐎠𐎼𐎿）的宫廷：卡尔纳号角开道，竖琴应答，双簧管持续低音，麻葛吟唱，框鼓、钹和青铜铃铛掌握节拍。音阶和奈伊笛是后世波斯的替代品，因为真正的律制已经失传。",
  "saracens:showcase": "阿拉伯传统说，歌唱始于沙漠中的“胡达”（حداء）——骆驼夫为让驼群前行而唱的号子，节奏与骆驼的步伐相合。伊斯兰以前，诗人们在集市和部落聚会上吟诵他们的颂诗“盖绥达”（قصيدة），城镇里则有歌女表演。拉弓的拉巴巴琴（ربابة）——一根马尾弦绷在蒙皮的琴框上——成了贝都因诗人的乐器，沙巴巴笛（شبابة）则属于牧人。贝都因诗人至今仍在咖啡炉旁伴着拉巴巴琴吟唱“纳巴提”（نبطي）诗歌，男人们排成行拍手起舞。本曲还加入了乌德琴、奈伊笛、驼铃，以及后来阿拉伯军队中的军乐：纳菲尔号（نفير）和纳卡拉定音鼓（نقارة）。",
  "abbasids:showcase": "阿拉伯艺术音乐源于歌女“基彦”（قيان），以及麦加和麦地那最早的一批著名歌手，他们借用了波斯和拜占庭的曲调。在阿拔斯时代的巴格达，它繁荣起来：易卜拉欣·毛西里（إبراهيم الموصلي）和他的儿子伊斯哈格（إسحاق）为哈里发们歌唱；据说是伊斯哈格学生的齐尔亚布（زرياب）把乌德琴（عود）带到了科尔多瓦，并被认为给它加上了第五根弦。铿迪（الكندي）和法拉比（الفارابي）著书论述其律制与调式，阿布·法拉吉·伊斯法哈尼则在《诗歌集》（كتاب الأغاني）中汇编了歌曲和歌手生平。这门艺术发展成了“马卡姆”（مقام）调式体系，至今仍能从乌德琴、卡龙琴（قانون）、奈伊笛（ناي）、雷巴布琴和里克手鼓（رق）中听到，本曲还加入了古代宫廷的布克号和纳卡拉鼓乐队。",
  "ayyubids:showcase": "黎凡特保存着已知最古老的成文旋律：乌加里特（𐎜𐎂𐎗𐎚）泥板上的一首胡里安颂歌，约公元前1400年，附有里拉琴的演奏说明。许多世纪后，大马士革（دمشق）和阿勒颇（حلب）成为阿拉伯音乐的重镇。诞生于安达卢斯的分节歌“穆瓦沙赫”（موشح）在阿勒颇找到了第二故乡，与之并存的还有“古杜德”（قدود）——把宗教与爱情诗句填入流行曲调的歌。苏非道堂保留着奈伊笛（ناي），赞颂歌手（منشدين）吟唱“迪克尔”赞念，苏丹的军乐队（طبلخانة）由纳菲尔号、大库斯鼓（كوس）和卡萨特钹组成，按固定时辰演奏。阿勒颇的歌手至今仍以乌德琴、卡龙琴（قانون）、雷巴布琴、卡曼贾琴、奈伊笛和达布卡鼓演出“瓦斯拉”组曲。",
  "turks:showcase": "乌古斯人从草原带来了科布兹琴（قوپوز）。他们的歌者“奥赞”（ozan）在宴会上吟唱颂歌和故事；在几百年后才写定的《先祖科尔库特书》（كتاب دده قورقود）中，睿智的长者科尔库特手持科布兹琴为英雄祝福、命名。古突厥如尼文碑铭提到了乌古斯（𐰆𐰍𐰔），却没有记下他们的任何歌曲，所以它们听起来如何已无从知晓。在安纳托利亚和高加索，奥赞变成了“阿舍克”（aşık）——游吟诗人，科布兹琴变成了长颈的巴拉玛萨兹琴（bağlama saz）。牧人们保留了卡瓦尔笛（kaval），婚礼保留了苏尔奈管和达乌尔鼓。本曲交织着科布兹琴、卡瓦尔笛、丘拉琴、迪万萨兹琴、凯门切琴、苏尔奈管、达乌尔鼓和齐尔钹。",
  "ottomans:showcase": "安纳托利亚突厥音乐融合了草原与伊斯兰两种根源。在科尼亚，鲁米（مولانا）的追随者——梅夫拉维教团（مولوی）——让奈伊笛（نی）在旋转仪式中成为灵魂之声。由苏尔奈管、博鲁号、科斯定音鼓、达乌尔鼓和齐尔钹组成的军乐队（مهتر）在大军前方行进，也在宫中演奏；欧洲人在“土耳其风格”（alla turca）中模仿它的声音。在宫廷里，伊特里（عطری）等作曲家塑造了“法瑟尔”（fasıl）组曲和“马卡姆”（مقام）调式体系，坎特米尔则在1700年前后用自创的记谱法记下了数百首器乐曲。坦布尔琴（طنبور）、卡龙琴（قانون）和凯门切琴至今仍在演奏法瑟尔，军乐队也重新在仪式中行进。",
  "armenians:showcase": "亚美尼亚教会圣歌“沙拉坎”（շարական）在约公元405年创制字母之后发展起来；梅斯罗普·马什托茨（Մեսրոպ Մաշտոց）被认为创作了早期的圣歌，中世纪的抄写员用“哈兹”（խազ）纽姆符号记写它们，其确切读法后来部分失传了。乡村生活保留了劳动歌、挽歌，以及伴着苏尔奈管和达霍尔鼓（դհոլ）的舞蹈。游吟诗人“阿舒赫”（աշուղ）唱着情歌；其中最著名的萨亚特-诺瓦（Սայաթ-Նովա）在18世纪弹奏卡曼恰琴（քամանչա）。1900年前后，神父科米塔斯（Կոմիտաս）收集了数千首民歌，并把许多改编成合唱。杜杜克（դուդուկ）——一种杏木制的双簧管——在“达姆”持续低音之上歌唱，伴以什维笛、卡龙琴和塔尔琴，至今仍是亚美尼亚音乐的声音。",
  "georgians:showcase": "格鲁吉亚人以三个声部歌唱，这一传统比任何文字记载都要古老。10世纪，米卡埃尔·莫德列基利（მიქაელ მოდრეკილი）汇编了一部标有纽姆符号的教会圣歌巨著。在乡村，各地区保留着自己的风格：斯瓦涅季（სვანეთი）粗粝紧密的和声，卡赫季（კახეთი）悠长的宴席歌，古里亚（გურია）跳跃的“克里曼丘利”（კრიმანჭული）真假声转换唱法。在“苏普拉”（სუფრა）宴席上，男人们伴着潘杜里琴（ფანდური）和琼古里琴（ჩონგური）歌唱，还有萨拉穆里笛（სალამური）、丘尼里提琴、古达斯特维里风笛（გუდასტვირი）、多利鼓和迪普利皮托对鼓。卡赫季歌曲《恰克鲁洛》（ჩაკრულო）的录音被收进1977年发射的旅行者号金唱片，飞出了太阳系。",
  "huns:showcase": "匈人的曲调、乐器和歌词无一留存。最好的见证者是普里斯库斯（Πρίσκος），这位来自君士坦丁堡的使节于449年在阿提拉的宫廷赴宴：火把点起时，两个人站在国王面前，唱起他们为他的胜利和勇气所作的歌。宾客们听得入神；有人变得激昂，老人们则为自己力气不再而落泪。然后一个弄臣和一个傻子逗得满堂大笑。所以本曲是一种重构：它借用了后世突厥和蒙古牧人的草原之声——伊吉勒马头琴（игил）、托布秀尔琴（топшур）、查特汗筝、楚吾尔笛、卡尔格拉和呼麦喉音唱法、战号、萨满铃和框鼓。",
  "cumans:showcase": "库曼人——西部草原的钦察游牧骑手——几乎没有留下成文的音乐。14世纪商人和修士编写的《库曼语汇编》（Codex Cumanicus）记录了他们的语言、谜语和译成库曼语的拉丁圣歌，却没有旋律。他们的声音通过亲族——哈萨克人和其他钦察民族——流传下来。在哈萨克传说中，歌者阔尔克特（Қорқыт）制作了第一把库布孜琴（қобыз）——一种马尾弦提琴——用来对抗死亡。史诗歌手“吉劳”（жырау）吟唱史诗，冬不拉（домбыра）弹奏者用器乐曲“奎依”（күй）讲述完整的故事；19世纪的库尔曼加济（Құрманғазы）创作了其中的名篇。本曲是依据这一传统所作的重构，使用斯布兹格笛、杰特根筝、凯尔奈号、阿萨塔亚克响杖和达乌尔帕兹鼓。",
  "tatars:showcase": "伏尔加河和乌拉尔地区的鞑靼与巴什基尔歌曲建立在五声音阶上，以悠长而富有装饰的旋律线演唱。库赖笛（курай）——用干植物茎秆制成的竖吹笛——是牧人最古老的声音，巴什基尔的“乌兹利亚乌”（өҙләү）喉音唱法在它下方低吟。库布兹口簧琴（кубыз）在家中和牧场上铮铮作响。伊斯兰带来了吟唱的祈祷“穆纳贾特”（мөнәҗәт），“拜耶特”（бәет）则用诗句讲述事件的长篇故事。长歌“奥曾柯伊”（озын көй）和轻快的舞曲至今仍与敦布拉琴、基尔库布兹提琴、库斯列筝以及乡村里的手风琴一起流传；本曲还加入了手鼓（doira）、马铃和卡尔奈长号。",
  "golden-horde:showcase": "在金帐汗国（Алтан Орд），蒙古统治者生活在钦察牧人之中，他们的音乐就像他们的营地一样交融。旅行者看到蒙古宫廷的宴会离不开酒和音乐，但没有曲调被记录下来。流传下来的是牧人自己的声音。马头琴（морин хуур）在传说中与牧人苏和·那木吉勒（Хөхөө Намжил）相连，他用心爱的飞马的骨头和鬃毛刻成了它。呼麦（хөөмий）歌手从一个嗓音中唱出两个音，长调（уртын дуу）则把寥寥几个字铺展在宽广而缓慢的旋律上。本曲是依据这些活着的艺术所作的重构，使用冬不拉、雅托噶筝、林贝笛、布列号、卡尔奈长号、纳卡拉鼓和锣。",
  "berbers:showcase": "阿马齐格音乐比任何关于它的文字都要古老，它活着的形式是最好的证据。在中阿特拉斯山，全村人跳“阿希杜斯”（ⴰⵃⵉⴷⵓⵙ）舞，男男女女肩并肩排成行，随着本迪尔框鼓的节拍应和诗人的诗句；在高阿特拉斯山，“阿赫瓦什”（ⴰⵃⵡⴰⵛ）在夜晚填满村中广场。苏斯地区的游吟诗人乐师“尔瓦伊斯”（ⵔⵔⵡⴰⵢⵙ）伴着里巴布提琴和卢塔尔琴歌唱。在图阿雷格人中，只由女性演奏的单弦提琴伊姆扎德（ⵉⵎⵣⴰⴷ）为男人的诗歌伴奏，女人们围着廷德臼鼓歌唱。本曲中，加伊塔唢呐、卡斯巴笛、金布里琴、特贝尔鼓和卡拉卡布铁响板也加入其中。",
  "ethiopians:showcase": "埃塞俄比亚教会音乐被归功于圣雅列德（ቅዱስ ያሬድ）——6世纪阿克苏姆（አክሱም）的一位执事，传说他从天上领受了圣咏，并把一年的圣歌按三种调式编排：格埃兹、埃泽尔和阿拉赖。唱诗学者“德布泰拉”（ደብተራ）至今仍伴着凯贝罗鼓（ከበሮ）和采纳采尔叉铃（ጸናጽል）吟唱这种“泽马”（ዜማ），读的是16世纪定型的一套小符号记谱。统治者的到来由内加里特定音鼓（ነጋሪት）和长号宣告。教会之外，游吟歌手“阿兹马里”（አዝማሪ）伴着单弦的马辛科琴（ማሲንቆ）唱着机智的诗句，克拉尔里拉琴（ክራር）和瓦辛特笛（ዋሽንት）在宴席上演奏，巨大的贝根纳琴（በገና）在祈祷歌背后嗡鸣。旋律遵循“凯涅特”（ቅኝት）调式，如“特兹塔”（ትዝታ）、巴蒂和安巴塞尔。",
  "malians:showcase": "曼丁音乐由“杰利”（ߖߋߟߌ）守护——世袭的格里奥，用歌声铭记历史。《松迪亚塔》（ߛߎ߲ߖߊߕߊ）史诗讲述杰利巴拉·法塞凯·库亚特如何弹奏巫王苏曼古鲁的魔法巴拉丰木琴；据说正是那件乐器的“索索巴拉”（Sosso Bala）至今仍由库亚特家族保存在尼亚加索拉。1352年，伊本·白图泰（ابن بطوطة）看到格里奥杜加在曼萨·苏莱曼（منسا سليمان）面前演奏一架用芦苇和葫芦做成的巴拉丰木琴。恩戈尼琴历史悠久，而21弦的科拉琴是后来才在西部曼丁地区发展起来的。杰利家族至今仍伴着科拉琴、巴拉丰木琴和恩戈尼琴唱颂歌和松迪亚塔史诗，本曲还加入了博隆低音竖琴、索库提琴、富拉笛、象牙号以及金贝鼓和敦敦鼓。",
  "hausa:showcase": "豪萨音乐属于有城墙的集镇和埃米尔的宫廷。宫廷乐师吹奏长长的卡卡基号（kakaki）、阿尔盖塔唢呐（algaita），敲击坦巴里定音鼓（tambari），这是统治者在场的声音，在星期五和盛大的萨拉节日上响起，那时骑手们骑马参加“哈万萨拉”（hawan Sallah）游行。赞颂歌手“马罗卡”（maroka）和鼓手“马卡达”（makaɗa）带着卡兰古说话鼓（kalangu）为从农民到屠夫的各种赞助人服务，每个行业都有自己的乐师。戈杰提琴（goje）和加拉亚琴（garaya）为“博里”（bori）伴奏——在豪萨兰（Ƙasar Hausa）比伊斯兰更古老的神灵附体仪式。豪萨歌手至今仍伴着戈杰提琴、卡兰古鼓、昆蒂吉琴、莫洛琴和萨雷瓦笛演出，宫殿里依然在双口铁铃“库盖”（kuge）声中响起卡卡基号。",
});
